(window.GIM_TS=window.GIM_TS||{})["Bava Batra.5"]={"from":120,"a":[["\u0003ואי\u0004 \u0005[ואם]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003\"נכסי\u0004 \u0005[נכסים]\u0006 שלי אני מוכר \u0003\"\u0004— \u0003אפילו בתי ועבדי\u0004 \u0005[בתים ועבדים]\u0006 בכלל זה.","ועוד בענין של \"מצרים הרחיב לו\" נדון המקרה הבא: המוכר שדה לחבירו, וכאשר תיאר בשטר המכר את גבולותיו \u0003מצר לו מצר אחד ארוך\u0004 מצד אחד של השדה, \u0003ומצר אחד קצר\u0004 מצידו הנגדי, \u0003אמר רב: לא קנה אלא כנגד הקצר,\u0004 שמניחים כי המצר הקצר הוא הגבול המציין את גודל השטח שמוכר לו, ואילו המצר הארוך נועד רק להגדיר באיזה שדה מדובר (\"מצרים הרחיב לו\").","\u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003רב כהנא ורב אסי לרב: ויקנה כנגד ראש תור,\u0004 כלומר, שיעשו קו אלכסוני בין קצות המצרים, הקצר והארוך, ויקנה את כל השטח שקו זה תוחם! \u0003שתיק\u0004 \u0005[שתק]\u0006 \u0003רב\u0004 ולא ענה להם.","ומעירים: \u0003ומודה רב, היכא דאיכא\u0004 \u0005[היכן שיש]\u0006 \u0003מצר\u0004 של שני שדות, של \u0003ראובן ו\u0004לידו \u0003שמעון, מחד גיסא\u0004 \u0005[מצד אחד]\u0006 של השדה הנמכר, \u0003ומצר לוי ויהודה מחד גיסא\u0004 \u0005[מצד אחד]\u0006 שמולו, וכתב בתיאור השדה מצד אחד ראובן ושמעון, ומן הצד השני רק לוי (או יהודה), שבמקרה כזה, \u0003מדהוה ליה למכתב ליה\u0004 \u0005[מתוך שהיה לו לכתוב לו]\u0006 בתיאור המצרים את שדהו של \u0003ראובן כנגד\u0004 (מול) זה של \u0003לוי,\u0004 או מצר של \u0003שמעון כנגד יהודה, ולא כתב ליה\u0004 \u0005[לו]\u0006 כך, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שאינו מתכוון למכור רק חצי השדה שבין מצרי ראובן ולוי, אלא \u0003כנגד ראש תור הוא\u0004 ש\u0003אמר ליה\u0004 \u0005[לו].\u0006","ועוד בעניינים של סימון מצרים: אם היה \u0003מצר ראובן\u0004 בצד \u0003מזרח ומערב\u0004 של השדה, \u0003ומצר שמעון\u0004 בצד \u0003צפון ודרום\u0004 שלו — אין די בכך שיכתוב \"שדה שבין שדות ראובן ושמעון\", אלא \u0003צריך למכתב ליה\u0004 \u0005[לכתוב לו]\u0006 בשטר המכר: \u0003\"מצר ראובן רוחין תרין\u0004 \u0005[\u0006מ\u0005שני צדדים],\u0006 \u0003ומצר שמעון רוחין תרין\u0004 \u0005[משני צדדים]\u0006","\u0003\".\u0004 שאם לא כן — יקבל רק מחצית מן השדה באלכסון, כעין משולש, שצלע אחת שלו היא אחד משדות ראובן, והאחרת — אחד משדות שמעון. \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לחכמים\u0005]\u0006 שאלה זו: אם \u0003סיים לו את הקרנות,\u0004 כלומר, הגדיר בדיוק רק את הפינות של השדה, \u0003מהו\u0004 הדין, האם מכר לו רק את הפינות, או את כל השדה כולו? וכן אם הגדיר את השדה אותו הוא מוכר שהוא \u0003כמין גאם\u0004 (זוית ישרה), שסימן לו את המצר משני צדדים סמוכים זה לזה בלבד, \u0003מהו\u0004 הדין, האם מכר לו את כל השדה, או רק את השטח הצמוד למצרים אלה?"],["אם אמר לו את מצרי השדה \u0003בסירוגין\u0004 (בדילוג) שלא פירש לו את כל אורך המצרים, אלא רק חלקים מסויימים מהם, \u0003מהו?\u0004 לכל אחת מן השאלות הללו לא נמצאה תשובה ולכן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","ובעיה דומה: המוכר לחבירו שדה, \u0003מצר לו מצר ראשון ומצר שני ומצר שלישי\u0004 של אותו שדה, אבל \u0003מצר רביעי לא מצר לו\u0004 כלל, מה דינו? \u0003אמר רב: קנה הכל,\u0004 את כל השדה, \u0003חוץ ממצר רביעי,\u0004 כלומר, חוץ מן התלם שעליו המצר עצמו, שבדרך כלל הוא ניכר ונבדל מן השדה. \u0003ושמואל אמר: אפילו מצר רביעי\u0004 קנה. \u0003ורב אסי אמר: לא קנה אלא תלם אחד על פני כולה\u0004 ליד המצרים שפירש לו.","ומסבירים את טעמו: \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 בענין זה בעיקרו של דבר \u0003כ\u0004שיטת \u0003רב,\u0004 ש\u0003אמר\u0004 שאם לא סימן את המצר משמע ש\u0003שיורי\u0004 \u0005[שיור]\u0006 \u0003שייר\u0004 אותו לעצמו ולא מכרו, \u0003ו\u0004אולם רב אסי מוסיף ואומר כי \u0003מ\u0004תוך ש\u0003שייר במצר, שייר נמי בכולהי\u0004 \u0005[גם כן בכלל\u0006 השדה\u0005]\u0006 ולא נתן לו קרקע אלא רק בסמוך למה שפירש.","\u0003אמר רבא, הלכתא\u0004 \u0005[ההלכה]\u0006 בענין זה היא: \u0003קנה הכל חוץ ממצר רביעי\u0004 כדברי רב. \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 דבר זה \u0003אלא\u0004 במצר ש\u0003לא מבלע\u0004 \u0005[מובלע]\u0006 בשטח שבין המצרים האחרים שמצידיו, אלא מעבר לשטח שביניהם, \u0003אבל\u0004 אם \u0003מבלע\u0004 \u0005[מובלע\u0006 ביניהם\u0005]\u0006 — \u0003קנה\u0004 אף אותו.","\u0003וכי לא מבלע נמי\u0004 \u0005[וכאשר אינו מובלע גם כן]\u0006 \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 שאינו קונה אותו \u0003אלא\u0004 במקרה \u0003דאיכא עליה ריכבא דדיקלא\u0004 \u0005[שיש עליו,\u0006 על המצר, \u0005שורה של דקלים ],\u0006 \u0003והוי\u0004 \u0005[ו\u0006גם \u0005הריהו]\u0006 בעל שטח זריעה של \u0003תשעת קבין, אבל\u0004 אם \u0003ליכא עליה ריכבא דדיקלא\u0004 \u0005[אין עליו שורת דקלים],\u0006 \u0003ולא הוי\u0004 \u0005[ואין הוא\u0006 בן\u0005]\u0006 \u0003תשעת קבין\u0004 — \u0003קנה.\u0004 ומעירים: \u0003מכלל\u0004 הדברים אתה למד \u0003דכי\u0004 \u0005[שכאשר]\u0006 המצר \u0003מובלע,\u0004 \u0003אף על גב דאיכא עליה ריכבא דדיקלא\u0004 \u0005[אף על פי שיש עליו שורת דקלים],\u0006 \u0003והוי\u0004 \u0005[והריהו]\u0006 בעל שטח של \u0003תשעת קבין\u0004 — \u0003קנה\u0004 אותו.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 את דברי רבא והמסקנה העולה מהם בלשון אחרת: \u0003אמר רבא, הלכתא\u0004 \u0005[ההלכה]\u0006 היא ש\u0003קנה הכל ואפילו\u0004 את ה\u0003מצר רביעי\u0004 כדעת שמואל. \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 דבר זה \u0003אלא\u0004 באופן \u0003דמבלע\u0004 \u0005[שמובלע]\u0006 המצר הרביעי בין המצרים שמצדיו, \u0003אבל\u0004 אם הוא \u0003לא מבלע\u0004 \u0005[מובלע]\u0006 — \u0003לא קני\u0004 \u0005[קונה].\u0006","\u0003וכי מבלע נמי\u0004 \u0005[וכאשר\u0006 הוא \u0005מובלע גם כן]\u0006 \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 שקונה \u0003אלא\u0004 באופן \u0003דליכא עליה ריכבא דדיקלא, ולא הוי\u0004 \u0005[שאין עליו שורת דקלים, ואין הוא\u0006 בן\u0005]\u0006 \u0003תשעת קבין, אבל\u0004 אם \u0003איכא עליה ריכבא דדיקלא והוי\u0004 \u0005[יש עליו שורת דקלים והוא]\u0006 בן \u0003תשעת קבין\u0004 — \u0003לא קנה.\u0004 ומעירים: \u0003מכלל\u0004 הדברים אנו למדים \u0003דכי\u0004 \u0005[שכאשר]\u0006 הוא \u0003לא מובלע, אף על גב דליכא עליה ריכבא דדיקלא\u0004 \u0005[אף על פי שאין עליו שורת דקלים]\u0006 \u0003ולא הוי\u0004 \u0005[ואינו]\u0006 בן \u0003תשעת קבין\u0004 — \u0003לא קני\u0004 \u0005[קנה].\u0006","ומסכמים: \u0003שמעינן מתרוייהו לישני\u0004 \u0005[שומעים אנו משתי הלשונות\u0006 הללו\u0005]\u0006 של \u0003רבא\u0004 על כל פנים, שאם שייר מצר רביעי, \u0003בשדה\u0004 עצמו \u0003לא שייר ולא מידי\u0004 \u0005[דבר].\u0006 \u0003ושמעינן נמי\u0004 \u0005[ושומעים אנו גם כן],\u0006 \u0003דהיכא דמבלע, וליכא עליה ריכבא דדיקלא\u0004 \u0005[שבמקום ש\u0006המצר \u0005מובלע, ואין עליו שורת דקלים]\u0006 \u0003ולא הוי\u0004 \u0005[ואינו]\u0006 בן \u0003תשעת קבין\u0004 — \u0003קנה\u0004 לשתי הלשונות. אם \u0003לא מבלע, ואיכא עליה ריכבא דדיקלא\u0004 \u0005[אינו מובלע, ויש עליו שורת דקלים],\u0006 \u0003והוי\u0004 \u0005[והינו]\u0006 בן \u0003תשעה קבין\u0004 — \u0003לא קנה\u0004 אותו.","אם הוא \u0003מבלע\u0004 \u0005[מובלע]\u0006 \u0003ואיכא עליה\u0004 \u0005[ויש עליו\u0006 שורת דקלים\u0005],\u0006 או שהוא \u0003לא מבלע\u0004 \u0005[מובלע]\u0006 \u0003וליכא עליה\u0004 \u0005[ואין עליו]\u0006 שורת דקלים, \u0003אתמר לה להאי גיסא, ואתמר לה להאי גיסא\u0004 \u0005[נאמר\u0006 הדבר \u0005לצד זה, ונאמר\u0006 הדבר \u0005לצד זה],\u0006 לפי השינוי בלשונו של רבא, וכיון שאין לנו הכרעה נוהגים בענין זה לפי \u0003שודא דדייני\u0004 \u0005[השלכת,\u0006 הכרעת \u0005הדיינים],\u0006 כלומר, יחליטו הדיינים לפי הנראה להם מה היתה כוונת המוכר.","\u0003אמר רבה:\u0004 אדם השותף עם חבירו בשדה, ומוכר חלקו לאדם אחר, אם אמר לו: \"אני מוכר לך \u0003פלגא דאית\u0004 \u0005[מחצית שיש]\u0006 \u0003לי בארעא\u0004 \u0005[בקרקע]\u0006 \", כוונתו שמוכר \u0003פלגא\u0004 \u0005[מחצית]\u0006 מן הקרקע כולה, כלומר, את כל חלקו בקרקע זו. אבל אם אמר \u0003\"פלגא בארעא דאית\u0004 \u0005[מחצית בקרקע שיש]\u0006 \u0003לי\"\u0004 — מכר לו \u0003ריבעא\u0004 \u0005[רבע]\u0006 מן הקרקע כולה, שהיא המחצית מהקרקע שלו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: מאי שנא הכי ומאי שנא הכי\u0004 \u0005[מה שונה כך ומה שונה כך]?\u0006 הרי אין שינוי הלשון מורה על הבדל זה בבירור! \u0003אישתיק\u0004 \u0005[שתק]\u0006 רבה ולא השיב.","\u0003אמר אביי, אנא סברי\u0004 \u0005[אני סברתי]:\u0006 \u0003מדאישתיק\u0004 \u0005[ממה ששתק]\u0006 הרי זה סימן כי \u0003קבולי\u0004 \u0005[לקבל]\u0006 \u0003קבלה\u0004 את דעתי, וחזר בו. \u0003ולא היא\u0004 \u0005[ואינו כן],\u0006 שכן \u0003חזינא הנהו שטרי דנפקי מבי מר\u0004 \u0005[ראיתי אותם שטרות\u0006 מכירה \u0005שיצאו מבית אדוני],\u0006 כלומר, מבית רבה, \u0003וכתיב בהו הכי\u0004 \u0005[וכתוב בהם כך]:\u0006 \u0003\"פלגא דאית\u0004 \u0005[מחצית שיש]\u0006 \u0003לי בארעא\u0004 \u0005[בקרקע]\u0006 \u0003\"\u0004— כוונתו \u0003פלגא\u0004 \u0005[מחצית\u0006 השדה כולו\u0005],\u0006 \u0003\"פלגא בארעא דאית\u0004 \u0005[מחצית בקרקע שיש]\u0006 \u0003לי\"\u0004 — \u0003ריבעא\u0004 \u0005[רבע\u0006 השדה כולו\u0005].\u0006","\u0003ואמר רבה:\u0004 מכר קרקע לחבירו, וכתב לו שלושה מצרים, ולגבי מצר רביעי כתב \u0003\"מצר ארעא\u0004 \u0003דמינה\u0004 \u0003פלגא\u0004 \u0005[גבולות קרקע שממנה נחצית]\u0006 קרקע זו \u0003\"\u0004— הרי מכר לו \u0003פלגא\u0004 \u0005[מחצית]\u0006 השדה, ושייר לעצמו מחצית השדה שליד מצר זה. אם אמר לו \u0003\"מצר ארעא דמינה פסיקא\u0004 \u0005[גבולות הקרקע שממנו נחתכת]\u0006 קרקע זו \u0003\"\u0004— מכר לו רק \u0003תשעה קבין\u0004 בשדהו, שהוא השיעור הקטן ביותר של שדה, וכל השאר שייר לעצמו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: מאי שנא הכי ומאי שנא הכי\u0004 \u0005[מה שונה כך ומה שונה כך]?\u0006 \u0003אישתיק\u0004 \u0005[שתק]\u0006 רבה. \u0003סבור מינה\u0004 \u0005[חשבו מכאן]\u0006 שכוונת אביי היא (ולכך הסכים רבה בשתיקתו) ש\u0003אידי ואידי פלגא\u0004 \u0005[זה וזה,\u0006 בשתי הלשונות, מוכר לו \u0005מחצית],\u0006"],["\u0003ולא היא\u0004 (ואינו כן), ש\u0003אמר רב יימר בר שלמיה: לדידי מפרשא לי מיניה\u0004 \u0005[לי נתפרש\u0006 הדבר \u0005ממנו]\u0006 מ\u0003אביי\u0004 עצמו: \u0003בין\u0004 שאמר לו \u0003\"מצר ארעא דמינה פלגא\"\u0004 \u0005[גבולות הקרקע שממנה נחצית\u0006 קרקע זו\u0005]\u0006 \u0003ובין \"מצר ארעא דמינה פסיקא\"\u0004 \u0005[גבולות הקרקע שממנו\u0006 היא \u0005נחתכת],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003\"אלין מצרנהא\"\u0004 \u0005[אלה גבולותיה]\u0006 — מכר לו \u0003פלגא\u0004 \u0005[מחצית],\u0006 \u0003לא אמר ליה\u0004 \u0005[לו]:\u0006 \u0003\"אלין מצרנהא\"\u0004 \u0005[אלה גבולותיה]\u0006 — מכר לו רק \u0003תשעה קבין.\u0004","ובענין דומה נאמר: \u0003פשיטא\u0004 \u0005[פשוט\u0006 הדבר\u0005]\u0006 שאם \u0003אמר \"יחלוק פלוני בנכסי\"\u0004 — כוונתו שנותן לו \u0003פלגא\u0004 \u0005[חצי],\u0006 אבל אם אמר \u0003\"תנו חלק לפלוני בנכסי\", מאי\u0004 \u0005[מה\u0006 הכוונה\u0005],\u0006 איזה חלק מן הנכסים צריך לתת לו?","\u0003אמר רבינא בר קיסי: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003האומר \"תנו חלק לפלוני בבור\"\u0004 — \u0003סומכוס אומר: אין\u0004 נותנים לאותו פלוני \u0003פחות מרביע\u0004 \u0005[מרבע]\u0006 המים שבבור. אם אמר \u0003\"\u0004תנו חלק לפלוני \u0003לחבית\"\u0004 — \u0003אין\u0004 נותנים לאותו פלוני \u0003פחות משמינית\u0004 מן המים שבבור. אם אמר כן \u0003\"לקדרה\"\u0004 — \u0003אין\u0004 נותנים לאותו פלוני \u0003פחות\u0004 מאחד \u0003משנים עשר,\u0004 אם אמר כן \u0003\"לטפיח\"\u0004 (כלי לשתיה) — \u0003אין\u0004 נותנים לאותו פלוני \u0003פחות\u0004 מאחד \u0003מששה עשר.\u0004","ועוד במי שמכר ושייר חלק ממה שמכר, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בן לוי שמכר שדה לישראל, ואמר לו \"על מנת שמעשר ראשון\u0004 מן הפירות שיגדלו בשדה זו \u0003שלי\u0004 הוא \u0003\",\u0004 שאתה מתחייב לתת רק לי את המעשר הראשון (הניתן ללויים) משדה זה — \u0003מעשר ראשון שלו. ואם אמר \"\u0004על מנת שמעשר זה יהיה \u0003לי ולבניי\",\u0004 הרי אם \u0003מת\u0004 המוכר \u0003יתן לבניו;\u0004","\u0003ואם אמר לו\u0004 שתנאי זה קיים \u0003כל זמן שהשדה זו בידך,\u0004 הרי אם \u0003מכרה\u0004 הקונה \u0003וחזר ולקחה\u0004 (קנה אותה) — \u0003אין לו עליו כלום,\u0004 אין המוכר הראשון יכול לדרוש ממנו עוד את הזכות למעשר הראשון, שהשדה כבר יצא מתחת ידו.","על גוף הענין, שהמעשר הראשון שלו, שואלים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 יהא כך הדין? הלא \u0003אין אדם מקנה דבר שלא בא לעולם,\u0004 וכיצד יכול לקנות לו חלק מן התבואה שאיננה קיימת כלל! ומשיבים: \u0003כיון דאמר ליה\u0004 \u0005[ש\u0006הוא \u0005אומר לו]\u0006 \u0003\"על מנת שמעשר ראשון שלי\",\u0004 ממילא אפשר לומר ש\u0003שיורי שייריה\u0004 \u0005[שיור שייר]\u0006 לעצמו את \u0003מקום\u0004 ה\u0003מעשר,\u0004 כאילו לא מכר אותו כלל, ומקום זה הרי הוא דבר שנמצא בעולם, ולכן פירותיו שייכים למוכר.","\u0003אמר ריש לקיש, זאת אומרת: המוכר בית לחבירו, ואמר לו על מנת שדיוטא\u0004 (קומה) \u0003העליונה שלי\u0004 — הרי \u0003דיוטא העליונה שלו.\u0004"],["ושואלים: \u0003למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה]\u0006 אמר ריש לקיש שתהא דיוטא עליונה שלו? והרי בין כה וכה היא שלו, שהרי לא מכר לו אלא את התחתונה! \u0003רב זביד אמר:\u0004 לומר \u0003שאם רצה להוציא בה\u0004 מדיוטא זו \u0003זיזין\u0004 אל תוך החצר, שאף אותה מכר לקונה — \u0003מוציא.\u0004 \u0003רב פפא אמר:\u0004 לומר \u0003שאם רצה לבנות עלייה על גבה,\u0004 כלומר, שאם נפלה דיוטא זו ורוצה לבנות במקומה — \u0003בונה.\u0004","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004דעת \u0003רב זביד, היינו דקתני\u0004 \u0005[זהו ששנה]\u0006 ריש לקיש \u0003\"זאת אומרת\",\u0004 שמדברי הברייתא בענין מעשר הוא למד שאף כאשר אין המוכר משייר לעצמו במפורש חלק מן המקום שמכר, אנו מפרשים את ייתור לשונו בדרך זו, ששייר לעצמו את מקום הזיזים. \u0003אלא לרב פפא מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"זאת אומרת\"?\u0004 הרי אין בזכות לחזור ולבנות את הדיוטא שלו משום שיור במה שמכר, ולא מן הברייתא למדנו דבר זה! ואומרים: אכן \u0003קשיא\u0004 \u0005[קשה\u0006 הדבר\u0005].\u0006","\u0003אמר רב דימי מנהרדעא: האי מאן דמזבין ליה ביתא לחבריה\u0004 \u0005[מי שמוכר בית לחבירו],\u0006 \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003כתב ליה\u0004 \u0005[לו]\u0006 שמוכר גם \u0003\"עומקא ורומא\"\u0004 \u0005[עומק ורום],\u0006 \u0003צריך למכתב ליה\u0004 \u0005[לכתוב לו]\u0006 גם \u0003\"קני\u0004 \u0005[קנוי]\u0006 \u0003לך מתהום ארעא\u0004 \u0005[הקרקע]\u0006 \u0003ועד רום רקיעא\u0004 \u0005[הרקיע]\u0006 \u0003\",\u0004 \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003דעומקא ורומא בסתמא לא קני\u0004 \u0005[שעומק ורום בסתם אינו קונה]\u0006 אם לא נתפרש הדבר בהסכם, ואין לקונה זכות לחפור מתחת הבית או לבנות על גביו. כי \u0003אהני\u0004 \u0005[הועיל]\u0006 מה שכתב \u0003\"עומקא ורומא\"\u0004 \u0005[עומק ורום]\u0006 \u0003למיקנא עומקא ורומא\u0004 \u0005[לקנות עומק ורום],\u0006 \u0003ואהני\u0004 \u0005[הועיל]\u0006 מה שכתב \u0003\"מתהום ארעא\u0004 \u0005[הקרקע]\u0006 \u0003ועד רום רקיעא\u0004 \u0005[הרקיע]\u0006 \u0003\"\u0004\u0003למיקנא\u0004 \u0005[לקנות]\u0006 \u0003בור ודות\u0004 (בור הבנוי אבנים) \u0003ומחילות.\u0004","ומציעים: \u0003לימא מסייע ליה\u0004 \u0005[האם לומר\u0006 שאפשר \u0005לסייע לו]\u0006 ממה ששנינו במשנה: שהמוכר את הבית לא מכר \u0003לא את הבור ולא את הדות\u0004 \u0003אף על פי שכתב לו \"עומקא ורומא\"\u0004 \u0005[עומק ורום],\u0006 \u0003ואי סלקא דעתך בסתמא קני עומקא ורומא\u0004 \u0005[ואם עולה על דעתך\u0006 ש\u0005בסתם קונה עומק ורום],\u0006 \u0003ליהני \"עומקא ורומא\" למיקנא\u0004 \u0005[שיועיל\u0006 מה שכתב לו \u0005\"עומק ורום\" לקנות]\u0006 \u0003בור ודות ומחילות,\u0004 שהרי הוסיף תנאי בדבריו! ומשיבים: מדובר כאן במקרה ש\u0003לא כתב ליה\u0004 \u0005[לו]\u0006 \"עומק ורום\".","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"אף על פי שכתב לו\" קתני\u0004 \u0005[שנה]!\u0006 ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש לפרש את הדברים: \u0003אף על פי שלא כתב לו\u0004 — הרי זה \u0003כמי שכתב דמי\u0004 \u0005[נחשב],\u0006 \u0003למיקנא עומקא ורומא\u0004 \u0005[לקנות\u0006 את \u0005העומק והרום]\u0006 של הבית. שאנו מניחים שהיתה זו השמטה בשגגה. אבל \u0003למיקנא\u0004 \u0005[לקנות]\u0006 \u0003בור ודות ומחילות, אי\u0004 \u0005[אם]\u0006 \u0003כתב ליה\u0004 \u0005[לו]\u0006 במפורש \u0003\"עומקא ורומא\"\u0004 \u0005[עומק ורום]\u0006 — \u0003קני\u0004 \u0005[קונה],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא כתב\u0004 — \u0003לא קני\u0004 \u0005[קונה],\u0006 ואם כן אי אפשר להוכיח מכאן הוכחה גמורה.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003ולא\u0004 מכר לו בכלל הבית \u0003את הגג בזמן שיש לו\u0004 לגג \u0003מעקה גבוה עשרה טפחים;\u0004"],["\u0003ואי סלקא דעתך בסתמא קני עומקא ורומא\u0004 \u0005[ואם עולה על דעתך\u0006 לומר ש\u0005ב\u0006מוכר בית \u0005סתם קונה עומק ורום],\u0006 \u0003כי\u0004 \u0005[כאשר]\u0006 יש לו מעקה \u0003גבוה עשרה טפחים מאי הוי\u0004 \u0005[מה יש\u0006 בכך\u0005],\u0006 מדוע לא יהא הגג שייך לקונה? ומשיבים: \u0003כיון\u0004 ש\u0003גבוה עשרה טפחים\u0004 — \u0003חשיב\u0004 \u0005[חשוב\u0006 הוא\u0005]\u0006 כדבר לעצמו, ואינו נקנה עם הבית מן הסתם.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לענין זה ממה ש\u0003אמר ריש לקיש\u0004 לעיל, \u0003זאת אומרת: המוכר בית לחבירו, ואמר לו \"על מנת שדיוטא העליונה שלי\"\u0004 — \u0003דיוטא העליונה שלו; ואמרינן\u0004 \u0005[ואמרנו],\u0006 \u0003למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה]\u0006 נאמר הדבר? \u0003רב זביד אמר: שאם רצה להוציא בה זיזין\u0004 — \u0003מוציא, רב פפא אמר: שאם רצה לבנות עלייה על גבה\u0004 של אותה דיוטא — \u0003בונה;\u0004 ולפי דברי רב פפא תמוה:","\u0003ואי סלקא דעתך בסתמא לא קני\u0004 \u0005[ואם עולה על דעתך\u0006 לומר ש\u0005בסתם אינו קונה]\u0006 את האויר שמעל הבית, \u0003למה לי\u0004 לכתוב \u0003\"על מנת\"?\u0004 הרי האויר שמעל הבית שייך למוכר בכל מקרה! ומשיבים: \u0003אהני ליה\u0004 \u0005[הועיל לו]\u0006 \u0003\"על מנת\",\u0004 לומר \u0003דאי נפיל הדר בני לה\u0004 \u0005[שאם נופלת\u0006 דיוטא זו \u0005חוזר\u0006 ו\u0005בונה אותה],\u0006 שלולא תנאי זה לא היה יכול לחזור ולבנותה, אף אם לא מכר בכלל הבית את העומק והרום.","המוכר את הבית לא מכר עמו \u0003לא את הבור\u0004 \u0003ולא את הדות\u0004 שיבואר עניינו בגמרא, \u0003אף על פי שכתב לו\u0004 בשטר המכירה שמוכר לו \u0003עומקא ורומא\u0004 \u0005[עומק ורום].\u0006 שאין הבור והדות בכלל זה, והם נשארים ברשות המוכר. \u0003ו\u0004אולם \u0003צריך\u0004 המוכר \u0003ליקח\u0004 (לקנות) \u0003לו דרך\u0004 בתוך חלקו של הקונה, כדי להגיע לבורו, אלו \u0003דברי ר' עקיבא. וחכמים אומרים: אינו צריך ליקח לו דרך,\u0004 שאף הדרך בכלל מה ששייר.","\u0003ומודה ר' עקיבא, בזמן שאמר לו\u0004 במפורש \u0003\"חוץ מאלו\",\u0004 כלומר, הבור והדות, \u0003שאין צריך ליקח דרך,\u0004 שמן הסתם שייר לעצמו זכות לדרך.","במקרה אחר, שלא מכר את ביתו, אלא \u0003מכרן\u0004 את הבור והדות \u0003לאחר\u0004 — \u0003ר' עקיבא אומר:\u0004 הקונה אותם \u0003אינו צריך ליקח לו דרך, וחכמים אומרים: צריך ליקח לו דרך.\u0004","\u0003יתיב\u0004 \u0005[יושב\u0006 היה\u0005]\u0006 \u0003רבינא וקא קשיא ליה\u0004 \u0005[והיה קשה לו]:\u0006 \u0003היינו\u0004 \u0005[זהו]\u0006 \u0003בור היינו\u0004 \u0005[זהו]\u0006 \u0003דות!\u0004 ומה ההבדל ביניהם? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא תוספאה לרבינא: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר, ממה \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003אחד הבור ואחד הדות\u0004 בנויים \u0003בקרקע, אלא שהבור בחפירה\u0004 בלבד \u0003והדות בבנין.\u0004 כיוצא בזה מסופר, \u0003יתיב\u0004 \u0005[יושב\u0006 היה\u0005]\u0006 \u0003רב אשי וקא קשיא ליה\u0004 \u0005[והיה קשה לו]:\u0006 \u0003היינו\u0004 \u0005[זהו]\u0006 \u0003בור היינו\u0004 \u0005[זהו]\u0006 \u0003דות! אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר קשישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב חסדא לרב אשי: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003אחד הבור ואחד הדות בקרקע, אלא שהבור בחפירה והדות בבנין.\u0004","שנינו במשנה ש\u0003צריך\u0004 הקונה \u0003ליקח לו דרך,\u0004 אלו \u0003דברי ר' עקיבא; וחכמים אומרים: אינו צריך\u0004 ליקח לו \u0003דרך.\u0004 ומציעים: \u0003מאי לאו בהא קא מפלגי\u0004 \u0005[האם לא ב\u0006נושא \u0005זה הם חלוקים],\u0006"],["ש\u0003ר' עקיבא סבר\u0004 \u0005[סבור]:\u0006 \u0003מוכר בעין יפה מוכר,\u0004 ואם לא פירש שמשייר דבר בידו — מכר הכל, \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003מוכר בעין רעה מוכר,\u0004 ומה שלא מכר בפירוש לא מכר, \u0003ודקאמר נמי בעלמא\u0004 \u0005[ומה שנאמר גם כן בכלל]\u0006 ש\u0003ר' עקיבא לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 ש\u0003אמר מוכר בעין יפה מוכר,\u0004 נאמר כי \u0003מהכא\u0004 \u0005[מכאן\u0006 הוא נלמד\u0005]?\u0006","ודוחים: \u0003ממאי\u0004 \u0005[ממה,\u0006 מנין\u0005]\u0006 אתה מוכיח זאת? \u0003דלמא\u0004 \u0005[שמא]\u0006 כאן יש טעמים אחרים לדעתם: \u0003ר' עקיבא סבר\u0004 \u0005[סבור]:\u0006 \u0003אין אדם רוצה שיתן מעותיו\u0004 עבור הבית \u0003וידרסוהו אחרים\u0004 והרי בעל הבור דורס דרך ביתו בבואו לבורו, \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003אין אדם רוצה שיטול מעות\u0004 עבור הבית \u0003ו\u0004אחרי כן \u0003יפרח באויר,\u0004 שלא יוכל להגיע לבורו. אבל אין הם חלוקים בעקרון הכללי של מכירה בעין יפה או לא!","\u0003ואלא\u0004 ההוכחה היא \u0003מסיפא\u0004 \u0005[מ\u0006מה ששנינו ב\u0005סופה]\u0006 של המשנה שם טעמיהם הפוכים: אם \u0003מכרן לאחר\u0004 את הבור והדות שבתוך ביתו, \u0003ר' עקיבא אומר: אינו צריך\u0004 הקונה \u0003ליקח לו דרך\u0004 אותו בור, \u0003וחכמים אומרים: צריך,\u0004 ומכאן יש להסיק שהדבר תלוי בטעם של מכירה בעין יפה.","ודוחים: \u0003דלמא בהאי פליגי\u0004 \u0005[שמא בזה\u0006 הם \u0005חלוקים],\u0006 ש\u0003ר' עקיבא סבר\u0004 \u0005[סבור]:\u0006 \u0003בתר דעתא\u0004 \u0005[אחר הדעת]\u0006 של ה\u0003לוקח\u0004 (הקונה) \u0003אזלינן\u0004 \u0005[\u0006\u0005אנו הולכים],\u0006 ואף זכות המעבר שלו היא, \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003בתר דעתא\u0004 \u0005[אחר הדעת]\u0006 של ה\u0003מוכר אזלינן\u0004 \u0005[אנו הולכים]!\u0006","\u0003ואלא\u0004 יש להוכיח \u0003מהא\u0004 \u0005[מזו]\u0006 ששנינו: המוכר שדה לחבירו, לא מכר בכלל זה \u0003לא את הבור ולא את הגת ולא את השובך\u0004 שבתוכו, \u0003בין\u0004 שהם \u0003חרבין\u0004 (לא פעילים כעת) \u0003בין\u0004 שהם \u0003ישובין; וצריך\u0004 המוכר \u0003ליקח לו דרך\u0004 על מנת להשתמש בה, אלו \u0003דברי ר' עקיבא, וחכמים אומרים: אינו צריך;\u0004","\u0003הא תו\u0004 \u0005[\u0006מחלוקת \u0005זו עוד]\u0006 \u0003למה לי\u0004 לומר? הרי לכאורה הוא כדין המוכר בית! \u0003אלא לאו הא קא משמע לן\u0004 \u0005[האם לא\u0006 דבר \u0005זה השמיע לנו],\u0006 ש\u0003ר' עקיבא סבר\u0004 \u0005[סבור]:\u0006 \u0003מוכר בעין יפה מוכר\u0004 ומכר הכל, וצריך לקנות דרך לבורו, \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003מוכר בעין רעה מוכר\u0004 ולא מכר את הדרך אליו?","ודוחים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 למרות שאותם טעמים קיימים בבית ובשדה, \u0003אשמועינן\u0004 \u0005[השמיע לנו]\u0006 דין זה ב\u0003בית, וקא משמע לן\u0004 \u0005[והשמיע לנו]\u0006 גם ב\u0003שדה. וצריכא\u0004 \u0005[וצריך]\u0006 שייאמרו שני הדברים, \u0003דאי אשמועינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 ב\u0003בית\u0004 בלבד, היינו אומרים שהקונה מקפיד שלא יעברו דרך ביתו \u0003משום דבעי צניעותא\u0004 \u0005[ש\u0006הוא \u0005צריך צניעות],\u0006 ואינו רוצה באנשים הנכנסים לביתו, ומשום כך סבור ר' עקיבא שאם לא נאמר הדבר במפורש, אין למוכר זכות מעבר לבורו, \u0003אבל שדה\u0004 שהוא פתוח וגלוי — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא;\u0004 ולהיפך,","\u0003ואי אשמועינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 רק ב\u0003שדה,\u0004 הייתי אומר שטעם הדבר שבסתם אין למוכר דרך הוא \u0003משום דקשי ליה דוושא\u0004 \u0005[שקשה לו\u0006 לשדה \u0005דריסת הרגל],\u0006 \u0003אבל בית\u0004 — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 ולכן אנו זקוקים שיפרשו לנו בשני המקרים!","\u0003אלא\u0004 יש להוכיח דבר זה \u0003מסיפא\u0004 \u0005[מ\u0006מה ששנינו ב\u0005סופה\u0006 של אותה משנה\u0005]:\u0006 \u0003מכרן לאחר\u0004 — \u0003ר' עקיבא אומר: אינו צריך ליקח לו דרך, וחכמים אומרים: צריך;\u0004","\u0003הא תו\u0004 \u0005[זו עוד]\u0006 \u0003למה לי? היינו הך\u0004 \u0005[זהו זה],\u0006 מאותם טעמים עצמם נחלקו ר' עקיבא וחכמים לגבי בית! \u0003אלא לאו הא קא משמע לן\u0004 \u0005[האם לא דבר זה השמיע לנו],\u0006 ש\u0003ר' עקיבא סבר\u0004 \u0005[סבור]:\u0006 \u0003מוכר בעין יפה מוכר, ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003מוכר בעין רעה מוכר?\u0004 ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכן הוא.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בפסק ההלכה, \u0003רב הונא אמר\u0004 בשם \u0003רב:\u0004"],["\u0003הלכה כדברי חכמים, ורב ירמיה בר אבא אמר\u0004 בשם \u0003שמואל: הלכה כר' עקיבא. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב ירמיה בר אבא לרב הונא: והא זמנין סגיאין אמריתה קמיה\u0004 \u0005[הרי פעמים רבות אמרתי אותה לפני]\u0006 \u0003רב: הלכתא\u0004 \u0005[הלכה]\u0006 \u0003כר' עקיבא, ולא אמר לי ולא מידי\u0004 \u0005[דבר],\u0006 משמע שהוא סובר שלא כפי שאמרת בשמו! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003היכי תניתה\u0004 \u0005[איך שנית\u0006 את המשנה\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003איפכא תנינא\u0004 \u0005[ההיפך שניתי],\u0006 כלומר, שבגירסת המשנה שלו היו הדעות הפוכות. אמר לו: \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003לא אמר לך ולא מידי\u0004 \u0005[דבר],\u0006 שהרי אם הופכים את הדעות, דברי חכמים במשנה הם דברי ר' עקיבא לשיטתך.","על דברי רב ושמואל בענין זה, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: לימא אזדו לטעמייהו\u0004 \u0005[האם לומר\u0006 שהם \u0005הולכים\u0006 בענין זה \u0005לשיטתם],\u0006 ש","\u0003אמר רב נחמן אמר שמואל: האחין שחלקו\u0004 את נחלת אביהם — \u0003אין להן לא דרך זה על זה\u0004 כפי שהיה שם קודם לכן, \u0003ולא\u0004 זכות לשים \u0003סולמות זה על זה, ולא\u0004 זכות \u0003חלונות זה על זה\u0004 למנוע מן האחר לבנות מולם, \u0003ולא\u0004 להעביר \u0003אמת המים זה על זה.\u0004","והוסיף: \u0003והזהרו בהן, שהלכות קבועות הן. ורב אמר:\u0004 בכל המקרים האלה \u0003יש להן.\u0004 ונמצא שהם הולכים כל אחד לשיטתו, שלדעת שמואל האחים (שהם כמוכרים) מכרו זה לזה בעין יפה ולא שמרו לעצמם זכויות, ולדעת רב בעין רעה מוכרים.","ומעירים: אף שכן הוא, \u0003צריכא\u0004 \u0005[צריכים]\u0006 הדברים להיאמר פעם נוספת ואינם נלמדים זה מזה, \u0003דאי אשמועינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 רק \u0003בההיא\u0004 ביחס לאחים שחלקו, היינו אומרים \u0003בההיא קאמר\u0004 \u0005[אמר]\u0006 \u0003רב\u0004 שלאחים יש דרך זה על זה, \u0003משום דאמר ליה\u0004 \u0005[שאומר לו]\u0006 אח אחד לחבירו: \u0003בעינא למידר ביה כי היכי דדרו ביה אבהתי\u0004 \u0005[רוצה אני לגור בו כמו שגרו בו אבותי],\u0006 שהיתה להם דרך והיה להם זכות שימוש בכל הדברים. \u0003תדע\u0004 שיש ממש בטענה כזו, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"תחת אבתיך יהיו בניך\"\u0004 (תהלים מה יז), \u0003אבל בהא\u0004 \u0005[בזו]\u0006 במכירה סתם, \u0003אימא מודי ליה\u0004 \u0005[אמור\u0006 ש\u0005מודה לו]\u0006 \u0003לשמואל\u0004 שבעין יפה מוכר.","ולהיפך, \u0003ואי איתמר בהא\u0004 \u0005[ואם היה נאמר\u0006 רק \u0005בזו\u0006 במכר\u0005],\u0006 היינו אומרים: \u0003בהך קאמר\u0004 \u0005[בזו אמר]\u0006 \u0003שמואל\u0004 שלא שייר לעצמו הדרך, משום שבעין יפה מוכר, \u0003אבל בהא\u0004 \u0005[בזו],\u0006 באחים שחלקו, \u0003אימא מודי ליה\u0004 \u0005[אמור\u0006 ש\u0005מודה לו]\u0006 \u0003לרב,\u0004 שהשיקול של \"כדרך שדרו אבותי\" גובר על כך, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו הדברים.","ולגופו של דבר \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן\u0004 שהיה ממשיך דרכו של שמואל, \u0003לרב הונא: הלכתא כוותין\u0004 \u0005[הלכה כמותינו],\u0006 \u0003או הלכתא כוותייכו\u0004 \u0005[הלכה כמותכם]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הלכתא כוותייכו\u0004 \u0005[הלכה כמותכם],\u0006 \u0003דמקרביתו לבבא דריש גלותא דשכיחי דייני\u0004 \u0005[שאתם קרובים לשער ראש הגולה שמצויים\u0006 שם \u0005דיינים]\u0006 ומשום כך בקיאים אתם יותר בדיני ממונות.","\u0003איתמר\u0004 \u0005[נאמר]:\u0006 \u0003שני בתים\u0004 שהיו \u0003זה לפנים מזה,\u0004 אם העביר את \u0003שניהם,\u0004 לשני אנשים שונים \u0003במכר,\u0004 או \u0003שניהם במתנה\u0004 — \u0003אין להן\u0004 זכות ל\u0003דרך זה על זה,\u0004 כלומר, זכות מעבר של הפנימי דרך ביתו של החיצון, ו\u0003כל שכן\u0004 אם נתן את ה\u0003חיצון במתנה ו\u0004את ה\u0003פנימי במכר\u0004 שאין לפנימי זכות למעבר על החיצון, שיש מקום להניח שנותן עדיפות למתנה.","וגם במקרה שמסר את ה\u0003חיצון במכר ופנימי במתנה, סבור מינה\u0004 \u0005[חשבו מכאן]\u0006 ש\u0003אין להן דרך זה על זה;\u0004","\u0003ולא היא\u0004 (ואינו כן), \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003במה דברים אמורים\u0004 שמשייר לעצמו זכויות במה שמוכר — \u0003במוכר, אבל בנותן מתנה נותן את כולן? אלמא\u0004 \u0005[מכאן],\u0006 כי \u0003מאן דיהיב\u0004 \u0005[מי שנותן]\u0006 \u0003מתנה\u0004 — \u0003בעין יפה יהיב\u0004 \u0005[נותן],\u0006 יותר מן המוכר. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 אנו צריכים לומר ש\u0003מאן דיהיב\u0004 \u0005[מי שנותן]\u0006 \u0003מתנה\u0004 — \u0003בעין יפה יהיב\u0004 \u0005[נותן],\u0006 ונותן לו זכויות יתירות מלקונה, ולכן יש לפנימי שקיבל את ביתו במתנה זכות מעבר דרך בית החיצון שקנה את הבית.","\u0003המוכר את הבית\u0004 — \u0003מכר\u0004 עמו \u0003את הדלת אבל לא\u0004 מכר \u0003את המפתח, מכר את המכתשת\u0004 ה\u0003קבועה\u0004 בקרקע \u0003אבל לא את\u0004 המכתשת \u0003המיטלטלת, מכר את האיצטרוביל,\u0004 החלק התחתון, הקבוע, של הריחיים, \u0003אבל לא את הקלת,\u0004 החלק העליון, האפרכסת שבה שופכים חיטים לריחיים, \u0003ולא את התנור ולא את הכירים\u0004 לפי שהם נחשבים כמיטלטלים. \u0003בזמן שאמר לו\u0004 המוכר: \u0003\"הוא,\u0004 הבית, \u0003וכל מה שבתוכו\u0004 אני מוכר לך \u0003\"\u0004"],["\u0003הרי כולן מכורין.\u0004","ומציעים: \u0003לימא, מתניתין\u0004 \u0005[האם לומר\u0006 ש\u0005משנתנו]\u0006 שמחלקת בין סוגים שונים של תשמישי הבית, היא ש\u0003לא כ\u0004שיטת \u0003ר' מאיר, דאי\u0004 \u0005[שאם]\u0006 תאמר שכשיטת \u0003ר' מאיר\u0004 היא, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמר\u0004 ר' מאיר: \u0003מכר את הכרם\u0004 — \u0003מכר תשמישי כרם\u0004 כולם, ואף את המיטלטלים, ואם כן הוא הדין במוכר את הבית!","ומשיבים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שמשנתנו כשיטת \u0003ר' מאיר,\u0004 יש להבדיל בין המקרים: \u0003התם\u0004 \u0005[שם]\u0006 בכרם מדובר בתשמיש \u0003קביע\u0004 \u0005[קבוע]\u0006 בכרם ולכן נמכר עמו, \u0003הכא\u0004 \u0005[כאן\u0006 בבית\u0005]\u0006 מדובר בתשמיש \u0003לא קביע\u0004 \u0005[\u0006ש\u0005אינו קבוע].\u0006 ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003מפתח דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003דלת קתני\u0004 \u0005[שנה],\u0006 \u0003מה דלת דקביעא\u0004 \u0005[ש\u0006היא \u0005קבועה],\u0006 \u0003אף מפתח\u0004 מדובר \u0003דקביע\u0004 \u0005[ש\u0006הוא \u0005קבוע]!\u0006 \u0003אלא מחוורתא\u0004 \u0005[מחוור],\u0006 \u0003מתניתין דלא\u0004 \u0005[\u0006ש\u0005משנתנו אינה]\u0006 \u0003כ\u0004שיטת \u0003ר' מאיר.\u0004","ומביאים ברייתא הנוגעת למשנתנו, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003המוכר את הבית\u0004 — \u0003מכר את הדלת ואת הנגר\u0004 (בריח) \u0003ואת המנעול\u0004 שבדלת, \u0003אבל לא את המפתח. מכר את המכתשת החקוקה\u0004 בקרקע, \u0003אבל לא את הקבועה\u0004 בה. \u0003מכר האיצטרוביל אבל לא את הקלת, לא את התנור ולא את הכירים ולא את הריחים; ר' אליעזר אומר:\u0004 כלל הוא, \u0003כל המחובר לקרקע הרי הוא כקרקע.\u0004","\u0003בזמן שאמר לו: \"הוא\u0004 הבית \u0003וכל מה שבתוכו\u0004 מכורים לך \u0003\"\u0004— במקרה זה \u0003הרי כולן מכורין,\u0004 בין תשמישים הקבועים ובין המיטלטלים, \u0003בין כך ובין כך,\u0004 בין שאמר לו כך ובין שלא אמר לו — \u0003לא מכר לא את הבור ולא את הדות ולא את היציע,\u0004 שהם נחשבים רשות בפני עצמה ואינם חלק מן הבית.","מתוך שהבאנו ברייתא זו, מביאים ענין אחר שנזכרה בו. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003צינור שחקקו,\u0004 כלומר, שעשה בו בית קיבול והריהו מעתה כלי, \u0003ולבסוף קבעו\u0004 בקרקע, אם עברו דרכו המים למקוה — \u0003פוסל את המקוה,\u0004 משום שמימיו נחשבים כמים שאובים. אם \u0003קבעו\u0004 תחילה \u0003ולבסוף חקקו\u0004 — \u0003אינו פוסל את המקוה.\u0004 ומעירים: \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]?\u0006 \u0003לא\u0004 שיטת \u0003ר' אליעזר\u0004 היא \u0003ולא\u0004 שיטת \u0003רבנן\u0004 \u0005[חכמים].\u0006","ושואלים: \u0003הי\u0004 \u0005[\u0006ל\u0005איזה\u0006 דבר מדברי\u0005]\u0006 \u0003ר' אליעזר\u0004 הכוונה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003ר' אליעזר\u0004 של מכירת \u0003בית,\u0004 שהוא סבור בברייתא שהובאה לעיל שכל המחובר לקרקע הריהו כבית, ונמכר עמו, \u0003דלמא היינו טעמא\u0004 \u0005[שמא זהו הטעם],\u0006 ש\u0003ר' אליעזר סבר\u0004 \u0005[סבור]:\u0006 \u0003מוכר בעין יפה מוכר, ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003מוכר בעין רעה מוכר,\u0004 ואינו מוכר אלא את תשמישי הבית עצמו, וכל השאר אף אם הוא מחובר לקרקע — אינו נמכר עם הבית. אבל אין כאן ענין לגבי קביעות דברים בכלל!","\u0003ואלא\u0004 נאמר שהכוונה לדברי \u0003ר' אליעזר\u0004 בענין \u0003כוורת דבורים. דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003כוורת דבורים\u0004 שמחוברת לקרקע בטיט, \u0003ר' אליעזר אומר: הרי היא כקרקע, ו\u0004משום כך \u0003כותבין עליה פרוזבול\u0004 שהוא שטר שמוסר מלווה לבית הדין, שעל ידו אין חובות הלווה נשמטים בשנת השמיטה, ואין כותבים שטר כזה אלא אם כן היתה ללווה קרקע כלשהי."],["\u0003ואינה מקבלת טומאה\u0004 כל זמן שהיא קבועה \u0003במקומה, והרודה\u0004 (האוסף) \u0003ממנה\u0004 דבש \u0003בשבת\u0004 — \u0003חייב חטאת\u0004 כמי שקוצר מן הקרקע.","\u0003וחכמים אומרים:\u0004 כוורת \u0003אינה כקרקע, ו\u0004משום כך \u0003אין כותבין עליה פרוזבול, ומקבלת טומאה\u0004 ואף \u0003במקומה, והרודה ממנה בשבת\u0004 — \u0003פטור.\u0004 ולכאורה עולה מכאן כי לדעת ר' אליעזר, דבר מיטלטל שקבעוהו בקרקע — הרי חלה עליו תורת קרקע לכל דבר, ושלא כדברי הברייתא לגבי צינור שחקקו ואחר כך קבעו, שמקבל טומאה. ומכאן שאינה כדעת ר' אליעזר.","יש לדחות זאת, \u0003התם כדאמר\u0004 \u0005[שם\u0006 יש להסביר \u0005כמו שאמר]\u0006 \u0003ר' אלעזר טעמא\u0004 \u0005[\u0006את \u0005הטעם],\u0006 ש\u0003אמר ר' אלעזר: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' אליעזר\u0004 בענין כוורת? לא משום שהיא מחוברת לקרקע, אלא משום \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויטבל אותה ביערת הדבש\"\u0004 (שמואל א יד, כז), והלשון \"יערה\" באה ללמד שדין הכוורת והדבש כדין עצי היער,","\u0003מה יער\u0004 — \u0003התולש ממנו בשבת חייב חטאת, אף דבש\u0004 — \u0003הרודה ממנו בשבת חייב חטאת.\u0004 ואם כן מתבסס ר' אליעזר בענין כוורת שדינה כקרקע על לימוד מיוחד, שאין כוחו יפה ללמד על שאר כלים המחוברים ושאינם מחוברים לקרקע, ואין ללמוד מכאן על דעתו בענין צינור!","\u0003אלא\u0004 צריך לומר שהכוונה היא לדברי \u0003ר' אליעזר\u0004 בענין \u0003דף\u0004 (לוח), \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003דף של נחתומין\u0004 (אופים) שלשים עליו את הלחם, \u0003שקבעו בכותל\u0004 — \u0003ר' אליעזר מטהר, וחכמים מטמאין,\u0004 משמע שר' אליעזר אומר שכל דבר שנקבע בקרקע או במצורף לה נעשה כקרקע, ולכן אינו מיטמא.","ומעתה, שהגענו למסקנה שמדובר בברייתא זו, שבים לשאלה ביחס לצינור: \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]\u0006 הלכה זו של צינור? לא כר' אליעזר ולא כחכמים, שכן \u0003אי\u0004 \u0005[אם]\u0006 כשיטת \u0003ר' אליעזר, אפילו חקקו\u0004 את הצינור \u0003ולבסוף קבעו\u0004 אינו מקבל טומאה, שהרי הוא אומר שהדף שנעשה כלי ואחר כך קבעו דינו כקרקע, \u0003אי רבנן\u0004 \u0005[אם\u0006 כשיטת \u0005חכמים],\u0006 \u0003אפילו קבעו ולבסוף חקקו נמי\u0004 \u0005[גם כן]\u0006 דינו צריך להיות ככלי, שהרי הם לא חילקו בדבר!","ומשיבים: \u0003לעולם\u0004 שיטת \u0003ר' אליעזר היא, ושאני\u0004 \u0005[ושונה]\u0006 דין של \u0003פשוטי כלי עץ,\u0004 כלומר, כלי עץ פשוטים שאין להם בית קיבול, שאינם מקבלים \u0003טומאה\u0004 מן התורה, אלא \u0003דרבנן\u0004 \u0005[מדברי סופרים].\u0006 ולכן סבור ר' אליעזר שכיון שנקבע הדף בכותל ניטלה ממנו אף טומאה זו. אבל צינור שחקקו הריהו מקבל טומאה מן התורה, ולכן פוסל את המקוה אף לאחר שקבעו.","ושואלים: \u0003מכלל\u0004 הדברים אתה לומד ל\u0003שאיבה\u0004 שדין זה שמים שאובים פוסלים במקוה, הוא \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 ולכן ר' אליעזר מחלק בין צינור שנחקק ואחר כך נקבע בקרקע, לבין צינור שנחקק רק לאחר שנקבע בקרקע?"],["\u0003והא קיימא לן\u0004 \u0005[והרי מוחזק בידינו]\u0006 שפסול שאיבה במקוה הוא רק \u0003דרבנן\u0004 \u0005[מדברי סופרים]!\u0006 \u0003ועוד, האמר\u0004 \u0005[הרי אמר]\u0006 \u0003ר' יוסי בן ר' חנינא\u0004 על המחלוקת בדף של נחתומים: \u0003בדף של מתכת מחלוקת,\u0004 וכלי של מתכת, אף על פי שהוא פשוט, הריהו מקבל טומאה מן התורה! ונמצא שלדעת ר' אליעזר אפילו כלי המקבל טומאה מן התורה, כיון שנקבע בקרקע בכך יצא מתורת כלי, וחוזרת השאלה: אם כן, כשיטת מי היא אותה ברייתא בענין צינור, שאם קבעו ואחר כך חקקו — אינו פוסל את המקוה?","ומשיבים: \u0003לעולם\u0004 הלכה זו בצינור כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 החולקים על ר' אליעזר \u0003היא,\u0004 שמטמאים דף (מתכת) של נחתומים שקבעו בכותל, \u0003ו\u0004לענין הצינור — \u0003שאני\u0004 \u0005[ושונה]\u0006 \u0003שאיבה\u0004 שכל כולה פוסלת את המקוה רק \u0003דרבנן\u0004 \u0005[מדברי סופרים].\u0006","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003אפילו\u0004 צינור אשר \u0003חקקו ולבסוף קבעו נמי\u0004 \u0005[גם כן]\u0006 לא יפסול את המקוה! ומשיבים: \u0003שאני התם דאיכא\u0004 \u0005[שונה שם ש\u0006על כל פנים \u0005יש]\u0006 \u0003תורת כלי עליו בתלוש,\u0004 ועד כדי כך לא הקלו בפסול שאובים.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב יוסף: מי גשמים שחשב עליהם\u0004 כשירדו שיועילו \u0003להדיח את האיצטרובלין\u0004 (בסיסי הריחיים) שמחוברים לקרקע, \u0003מהו ל\u0004ענין הכשר \u0003זרעים\u0004 בהם? שהרי כל מים שיורדים על דברמה לרצונו של אדם נחשבים כמים ששפך בכוונה תחילה, ומים כאלה מכשירים את הזרעים לקבל טומאה.","ומעירים: \u0003אליבא\u0004 \u0005[לפי שיטת]\u0006 \u0003ר' אליעזר\u0004 ש\u0003אמר: כל המחובר לקרקע הרי הוא כקרקע\u0004 — \u0003לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 השאלה, שהרי האיצטרובלין הם מחוברים לקרקע ודינם כקרקע, ומים היורדים על הקרקע, ואף לרצונו — אינם מכשירים לקבל טומאה. \u0003כי תיבעי\u0004 \u0005[ כאשר תישאל ]\u0006 \u0003לך\u0004 השאלה הרי זה \u0003אליבא דרבנן דאמרי\u0004 \u0005[לשיטת חכמים שאומרים]\u0006 שהמחובר לקרקע \u0003אינו כקרקע, מאי\u0004 \u0005[מה]\u0006 יהא הדין לענין הכשר זרעים? לשאלה זו לא נמצאה תשובה, ולכן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמיה בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף לרבה בריה\u0004 \u0005[בנו]\u0006 של \u0003רב הונא זוטי\u0004 \u0005[הקטן]\u0006 \u0003לנהרדעא\u0004 מכתב, ובו כתב כך: \u0003כי אתיא הך איתתא לקמך\u0004 \u0005[כאשר תבוא אישה זו לפניך]\u0006 (שעימה שלח את המכתב),"],["\u0003אגבה\u0004 \u0005[הגבה לה],\u0006 כלומר, גבה עבורה \u0003עישור\u0004 (עשירית) \u0003נכסי\u0004 \u0005[נכסים]\u0006 שמגיע לה, לפי מה שאמרו חכמים שאם מת האב ויש לו בת הצריכה להינשא הריהי צריכה לקבל עשירית מנכסי המקרקעין של האב, וגבה \u0003אפילו מאצטרובלי\u0004 של \u0003ריחיים\u0004 משום שגם הם נחשבים בכלל קרקע. \u0003אמר רב אשי: כי הוינן בי\u0004 \u0005[כאשר היינו בבית]\u0006 \u0003רב כהנא, מגבינן\u0004 \u0005[היינו מגבים]\u0006 לצורך זה \u0003אפילו מעמלא דבתי\u0004 \u0005[משכירות הבתים].\u0006 שכיון שהשכירות באה מן הבתים הרי אף היא דינה כקרקע.","\u0003המוכר את החצר\u0004 — \u0003מכר בתים, בורות, שיחין\u0004 (חפירות) \u0003ומערות\u0004 שבתוכה, \u0003אבל לא את המטלטלין\u0004 שבה. \u0003בזמן שאמר לו \"הוא וכל מה שבתוכו\"\u0004 — \u0003הרי כולן מכורין. בין כך ובין כך,\u0004 אפילו אמר \"כל מה שבתוכו\", \u0003לא מכר לא את המרחץ ולא את בית הבד שבתוכה,\u0004 לפי שיש להם שימוש לעצמם וגם אינם חלק בלתי נפרד מן החצר. \u0003ר' אליעזר אומר: המוכר את החצר\u0004 סתם — \u0003לא מכר אלא אוירה\u0004 (חללה) \u0003של חצר,\u0004 ולא מכר דבר שבתוכה, אף לא בתים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003המוכר את החצר\u0004 — \u0003מכר בתים החיצונים\u0004 שפתחם לחצר, \u0003ובתים הפנימים\u0004 שפתחם לבתים החיצוניים, \u0003ובית החולסאות\u0004 (מקום שיש בו חול). \u0003חנויות\u0004 שהיו \u0003פתוחות לתוכה\u0004 — \u0003נמכרות עמה, ושאין פתוחות\u0004 \u0003לתוכה\u0004 אלא לרשות הרבים או לחצר אחרת, אף על פי שבנויות בתוכה — \u0003אין נמכרות עמה.\u0004 אם היו \u0003פתוחות לכאן ולכאן\u0004 גם לחצר וגם לחוץ — \u0003אלו ואלו,\u0004 גם הפתוחות לתוכה, וגם הפתוחות לכאן ולכאן, \u0003נמכרות עמה. ר' אליעזר אומר: המוכר את החצר\u0004 — \u0003לא מכר אלא מילוסא\u0004 (חללה) \u0003של חצר.\u0004 ודנים בפרטי הברייתא.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 אם היו החנויות שבחצר \u0003פתוחות לכאן ולכאן\u0004 — \u0003נמכרות עמה.\u0004 ומקשים: \u0003והא תני\u0004 \u0005[והרי שנה]\u0006 \u0003ר' חייא: אין נמכרות עמה!\u0004 ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003הא\u0004 \u0005[זה,\u0006 בברייתא הראשונה\u0005]\u0006 מדובר באופן ש\u0003רוב תשמישתייהו לגו\u0004 \u0005[תשמישן\u0006 הוא \u0005לפנים],\u0006 והרי הן נמכרות עימה, \u0003הא\u0004 \u0005[זה,\u0006 בברייתא ששנה ר' חייא\u0005]\u0006 מדובר באופן ש\u0003רוב תשמישתייהו לבר\u0004 \u0005[תשמישן\u0006 הוא \u0005לחוץ],\u0006 ואינן נמכרות עימה.","שנינו במשנה (וכיוצא בזה בברייתא) ש\u0003ר' אליעזר אומר: המוכר את החצר\u0004 — \u0003לא מכר אלא אוירה של חצר\u0004 ולא את הבתים שבתוכה. \u0003אמר רבה: אי דאמר ליה\u0004 \u0005[אם שאומר לו]\u0006 \u0003\"דירתא\u0004 \u0005[דירה,\u0006 מקום מגורים\u0005]\u0006 אני מוכר לך \u0003\"\u0004— \u0003דכולי עלמא לא פליגי\u0004 \u0005[הכל אינם חולקים]\u0006 \u0003דבתי משמע\u0004 \u0005[שבתים משמעו]\u0006 והוא מוכר לו את הבתים עם החצר, \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 \u0003דאמר ליה \"דרתא\"\u0004 \u0005[שאומר לו\u0006 שמוכר \u0005חצר],\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' אליעזר, \u0005סבור]:\u0006 \u0003תרביצא משמע\u0004 \u0005[גינה משמעו]\u0006 השטח שבין הבתים של החצר, חלל החצר, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 סתם משנתנו, \u0005סבור]:\u0006 גם \u0003בתי משמע\u0004 \u0005[בתים משמעו].\u0006","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בלשון אחרת: \u0003אמר רבה: אי דאמר ליה\u0004 \u0005[אם שאומר]\u0006 שמוכר \u0003\"דרתא\"\u0004 — \u0003דכולי עלמא לא פליגי דבתי משמע\u0004 \u0005[הכל אינם חולקים ש\u0006גם \u0005בתים משמעו],\u0006 \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה במקרה \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 \u0003\"חצר\", מר סבר\u0004 \u0005[חכם זה,\u0006 ר' אליעזר \u0005סבור]:\u0006 \u0003חצר\u0004 — \u0003אוירא\u0004 \u0005[חלל]\u0006 \u0003משמע, ומר סבר\u0004 \u0005[וחכם זה סבור]:\u0006 \u0003כחצר המשכן\u0004 שהמשכן עצמו היה מצוי בתוכה.","\u0003ואמר רבה אמר רב נחמן: מכר לו חולסית,\u0004 מקום חולות, \u0003ומצולה,\u0004 חלקת נהר או אגם או ים, שמשתמשים בה לדייג או דבר אחר, אם \u0003החזיק בחולסית,\u0004 כלומר, עשה מעשה חזקה בה על מנת לגמור את מעשה הקנין — \u0003לא קנה מצולה,\u0004 וצריך לעשות בה מעשה קנין לחוד, וכן אם \u0003החזיק במצולה\u0004 — \u0003לא קנה חולסית.\u0004 ומקשים: \u0003איני\u0004 \u0005[וכן הוא]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר שמואל:\u0004 אם \u0003מכר לו עשר שדות בעשר מדינות\u0004 בשטר אחד, \u0003כיון שהחזיק באחת מהן\u0004 — \u0003קנה כולן!\u0004","ודוחים: \u0003התם\u0004 \u0005שם\u0006 \u0003הוא דסדנא דארעא חד\u0004 \u0005[שהסדן,\u0006 התשתית \u0005של הארץ אחד]\u0006 \u0003הוא,\u0004 \u0003וכולה חדא תשמישתא\u0004 \u0005[והכל שימוש אחד]\u0006 \u0003הוא,\u0004 ולכן קונה את כולן בבת אחת, אף על פי שלמראה העין אינן צמודות זו לזו. \u0003אבל הכא\u0004 \u0005[כאן]\u0006 בחולסית ומצולה \u0003הא תשמישתא לחוד, והא תשמישתא לחוד\u0004 \u0005[זה שימוש לחוד, וזה שימוש לחוד]\u0006 ולכן אינן נמכרות בחזקה אחת.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים],\u0006"],["\u0003אמר רבה אמר רב נחמן:\u0004 אם \u0003החזיק בחולסית קנה\u0004 בכך אף \u0003את ה\u0004\u0003מצולה.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכן הוא, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003אמר שמואל: מכר לו עשר שדות\u0004 בעשר מדינות, כיון שהחזיק באחת מהן — קנה כולן! ומסבירים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 שיש לשדות שימוש אחד, \u0003הוא\u0004 שאנו אומרים שיקנה, משום \u0003דסדנא דארעא חד\u0004 \u0005[שהסדן,\u0006 התשתית \u0005של הקרקע אחד]\u0006 \u0003הוא,\u0004 \u0003אבל הכא הא תשמישתא לחוד והא תשמישתא לחוד\u0004 \u0005[כאן זה שימוש לחוד וזה שימוש לחוד]\u0006 ולא יקנה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שבכל זאת בחזקה שמחזיק אחת מהן קונה אף את השניה.","\u0003המוכר בית הבד\u0004 — \u0003מכר\u0004 בכלל זה \u0003את הים ואת הממל ואת הבתולות,\u0004 שהם מכשירי בית הבד (ועניינם מבואר בגמרא), מפני שכולם קבועים בקרקע בית הבד. \u0003אבל לא מכר\u0004 בכלל בית הבד \u0003את העבירים ואת הגלגל ואת הקורה,\u0004 שהם מכשירי בית הבד המיטלטלים. \u0003ובזמן שאמר לו\u0004 שהוא מוכר \u0003\"הוא\u0004 (בית הבד) \u0003וכל מה שבתוכו\"\u0004 — \u0003הרי כולן מכורין. ר' אליעזר אומר: המוכר בית הבד\u0004 — \u0003מכר את הקורה\u0004 משום שהיא עיקרו של בית הבד.","ומבארים את המונחים השונים הנזכרים במשנה: \u0003\"ים\"\u0004 — \u0003טלפחא\u0004 (=עדשה), שהוא המקום העגול שבו שמים את הזיתים לכתישה, קודם כבישתם. \u0003\"ממל\"\u0004 — \u0003אמר ר' אבא בר ממל:\u0004 הכוונה היא למה שקרוי בארמית \u0003מפרכתא,\u0004 המכשיר בו פורכים וכותשים את הזיתים. \u0003\"בתולות\"\u0004 — \u0003אמר ר' יוחנן:\u0004 אלה \u0003כלונסות\u0004 עמודים \u0003של ארז שמעמידין בהן את הקורה.\u0004 \u0003\"עבירים\"\u0004 מהם? הריהם מה שנקרא בארמית \u0003כבשי,\u0004 לוחות עץ שמניחים על הזיתים, ועליהם מורידים את הקורה. \u0003\"גלגל\" —\u0004 \u0003חומרתא,\u0004 אבן עגולה שמניחים על הקורה. \u0003קורה\u0004 — היא ה\u0003קורה\u0004 הכבידה של בית הבד שכובשים בה את הזיתים.","ומביאים, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003המוכר בית הבד\u0004 — \u0003מכר את נסרים\u0004 שקבועים להחזיק בהם זיתים, \u0003ואת היקבים\u0004 מקום מאגר השמן, \u0003ואת המפרכות\u0004 שבהן פורכים וכותשים את הזיתים לפני הכבישה, \u0003ואת הריחים התחתונות\u0004 האבן התחתונה, הקבועה, \u0003אבל לא\u0004 את \u0003העליונה, ובזמן שאמר לו: \"הוא וכל מה שבתוכו\"\u0004 — \u0003הרי כולן מכורין. בין כך ובין כך,\u0004 גם אם אמר \"כל מה שבתוכו\", \u0003לא מכר\u0004 לו \u0003לא את העבירים\u0004 לוחות שמניחים על הזיתים תחת הקורה בשעת כבישה, \u0003ולא את השקין ולא את המרצופין\u0004 (שקי עור) שנושאים בהם את הזיתים, שכולם מיטלטלים, ואינם שייכים דווקא לבית הבד.","\u0003ר' אליעזר אומר: המוכר בית הבד\u0004 — \u0003מכר את הקורה\u0004 שכובשים בה את הזיתים, משום \u0003שלא נקרא בית הבד אלא על שום\u0004 (שם) ה\u0003קורה\u0004 שהיא הקרויה בד (עץ), והיא עיקרו של בית הבד.","\u0003המוכר את המרחץ\u0004 — \u0003לא מכר את הנסרין\u0004 ששמים על רצפת בית המרחץ \u0003ואת הספלין ואת הבלניות\u0004 (וילונות). \u0003בזמן שאמר לו: \"היא וכל מה שבתוכה\"\u0004 — \u0003הרי כולן מכורין. בין כך ובין כך, לא מכר\u0004 לו \u0003לא את המגורות\u0004 (מאגרים) \u0003של מים ולא את אוצרות של עצים,\u0004 שעליהם צריך לעשות הסכם מפורש.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003המוכר את המרחץ\u0004 — \u0003מכר את בית הנסרין\u0004 (מחסן הנסרים) \u0003ואת בית היקמין\u0004 (מחסן של כלים בשם זה) \u0003ואת בית הספלים ואת בית הוילאות, אבל לא\u0004 מכר \u0003את\u0004 ה\u0003נסרין עצמן ולא\u0004 את ה\u0003יקמין עצמן, ולא\u0004 את ה\u0003ספלים עצמן ולא\u0004 את ה\u0003וילאות עצמן,\u0004 לפי שהם מיטלטלים, \u0003ובזמן שאמר לו: \"היא וכל מה שבתוכה\"\u0004 — \u0003הרי כולן מכורין. בין כך ובין כך, לא מכר לו את הבריכות המספקות לו מים, בין\u0004"],["\u0003בימות החמה ו\u0004בין \u0003בימות הגשמים, ולא בית כינוס העצים. ואם אמר לו: \"בית המרחץ וכל תשמישיו אני מוכר לך\"\u0004 — \u0003כולן מכורין.\u0004","מסופר: \u0003ההוא\u0004 \u0005[\u0006אדם \u0005אחד]\u0006 ש\u0003אמר ליה לחבריה\u0004 \u0005[לו לחבירו]:\u0006 \u0003\"בית הבד וכל תשמישיו אני מוכר לך\", הויא הנהו חנואתא אבראי דהוו שטחו בהו שומשמי\u0004 \u0005[היו\u0006 שם \u0005אותן חנויות מבחוץ ש\u0006בנוסף לשימושן הרגיל \u0005היו שוטחים בהן שומשומים]\u0006 לייבשם, לפני שיפיקו מהם שמן, ונחלקו המוכר והקונה אם החנויות הללו הן בכלל המכר או לא. \u0003אתא לקמיה\u0004 \u0005[בא\u0006 הקונה \u0005לפני]\u0006 \u0003רב יוסף\u0004 בתביעה,","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003תנינא\u0004 \u0005[שנינו],\u0006 \u0003אם אמר: \"בית המרחץ וכל תשמישיו אני מוכר לך\"\u0004 — \u0003הרי כולן מכורין,\u0004 משמע שגם זה נמכר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרב יוסף, \u0003והא תני\u0004 \u0005[והרי שנה]\u0006 \u0003ר' חייא: אין כולן מכורין! אלא\u0004 יש לסכם ענין זה כמו ש\u0003אמר רב אשי: חזינן\u0004 \u0005[רואים אנו],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003\"בית הבד וכל תשמישיו ואלין מצרנהא\u0004 \u0005[ואלה גבולותיו]\u0006 \u0003\",\u0004 וכלל בתוכם גם את שטח החנויות — \u0003קני\u0004 \u0005[קנה]\u0006 את החנויות, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003לא קני\u0004 \u0005[קנה],\u0006 משום שהן בעצם אינן שייכות לבית הבד.","\u0003המוכר את העיר\u0004 — \u0003מכר\u0004 בכלל זה \u0003בתים, בורות שיחין ומערות, מרחצאות ושובכות, בית הבדין ובית השלחין\u0004 שיש בה, \u0003אבל לא את המטלטלין\u0004 שבה. \u0003ובזמן שאמר לו: \"היא וכל מה שבתוכה\", אפילו היו בה בהמה ועבדים\u0004 — \u0003הרי כולן מכורין. רבן שמעון בן גמליאל אומר: המוכר את העיר\u0004 — \u0003מכר\u0004 גם \u0003את הסנטר\u0004 יחד איתה. ובגמרא דנים מהו סנטר זה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אויא לרב אשי: שמעת מינה\u0004 \u0005[לומד אתה מכאן]\u0006 כי \u0003עבדא כמטלטלא דמי\u0004 \u0005[עבד כ\u0006דבר \u0005מיטלטל\u0006 הוא \u0005נחשב],\u0006 \u0003דאי כמקרקע דמי\u0004 \u0005[שאם כקרקע\u0006 הוא \u0005נחשב],\u0006 אם כן \u0003ניזדבן\u0004 \u0005[\u0006ש\u0005יימכר]\u0006 \u0003אגב מתא\u0004 \u0005[העיר].\u0006 והקשה לו: \u0003ואלא מאי\u0004 \u0005[מה]\u0006 אתה אומר, ש\u0003עבדא כמטלטלא דמי\u0004 \u0005[העבד כמיטלטל\u0006 הוא \u0005נחשב],\u0006 אם כן \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \"מכר \u0003אפילו\u0004 בהמה ועבדים\"? מה חידוש נוסף בכך? והרי עבד בכלל המיטלטלים!","\u0003אלא מאי אית\u0004 \u0005[מה יש]\u0006 \u0003לך למימר\u0004 \u0005[לומר]?\u0006 \u0003שאני\u0004 \u0005[\u0006יש \u0005שוני]\u0006 \u0003בין מטלטלא\u0004 \u0005[מיטלטל]\u0006 ש\u0003נייד ממטלטלא\u0004 \u0005[ממיטלטל]\u0006 ש\u0003לא נייד,\u0004 שכן היה מקום לומר שדין שונה להם, למרות שהם מיטלטלים. כמו כן \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 ש\u0003עבדא כמקרקע דמי\u0004 \u0005[העבד כקרקע\u0006 הוא \u0005נחשב],\u0006 \u0003שאני\u0004 \u0005[שונה]\u0006 יש להבחין לענין זה \u0003בין מקרקע\u0004 ש\u0003נייד,\u0004 כלומר, עבד, \u0003למקרקע\u0004 ש\u0003לא נייד.\u0004","שנינו במשנה ש\u0003רבן שמעון בן גמליאל אומר: המוכר את העיר\u0004 — \u0003מכר את הסנטר.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"סנטר\"? הכא תרגימו\u0004 \u0005[כאן תרגמו,\u0006 פירשו\u0005]:\u0006 \u0003בר מחווניתא,\u0004 כלומר, האיש הצופה, השומר את העיר. \u0003שמעון בן אבטולמוס אומר:\u0004 הכוונה היא \u0003באגי\u0004 השדות שסביב. ומעירים: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שסנטר הוא \u0003בר מחווניתא,\u0004 מסביר שרבן שמעון בן גמליאל סבור כי \u0003כל שכן באגי\u0004 \u0005[שדות]\u0006 נמכרים עם העיר, ואולם \u0003מאן דאמר באגי\u0004 \u0005[מי שאומר\u0006 שסנטר הוא \u0005שדות]\u0006 סבור: \u0003אבל בר מחווניתא לא מיזדבן\u0004 \u0005[נמכר].\u0006 ומנסים להביא ראיה לאחת מן הדעות.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003בית הבדים ובית השלחין\u0004 נמכרים עם העיר; \u0003סברוה\u0004 \u0005[חשבו\u0006 לומר בהלכה זו\u0005]:\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"שלחין\"\u0004 — \u0003באגי\u0004 \u0005[שדות]\u0006 של שלחין, שדות הצריכים להשקאה נוספת, ולא די להם במי הגשמים, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004הנותן מטר על פני ארץ \u0003ושלח מים על פני חוצות\"\u0004 (איוב ה, ו); ומעתה, \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר]\u0006 שסנטר הוא \u0003בר מחווניתא,\u0004 לפי זה \u0003אמר\u0004 ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 במשנתנו: \u0003באגי מיזדבני\u0004 \u0005[השדות נמכרים],\u0006 \u0003בר מחווניתא לא מיזדבן\u0004 \u0005[נמכר],\u0006 \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003רבן שמעון בן גמליאל למימר\u0004 \u0005[לומר]\u0006 ש\u0003אפילו בר מחווניתא נמי מיזדבן\u0004 \u0005[גם כן נמכר],\u0006 \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שסנטר הוא \u0003באגי\u0004 \u0005[שדות],\u0006 ה\u0003תנא קמא נמי הכי קאמר\u0004 \u0005[הראשון גם כן כך אמר]\u0006 שנמכרים, ובמה חולק רבן שמעון?","ודוחים: \u0003מי סברת מאי\u0004 \u0005[האם סבור אותה\u0006 ש\u0005מה\u0006 פירוש\u0005]\u0006 \u0003\"שלחין\"\u0004 — \u0003באגי\u0004 \u0005[שדות]?\u0006 \u0003לא, מאי\u0004 \u0005[מהם]\u0006 \u0003\"שלחין\"\u0004 — הכוונה היא \u0003גינונייתא\u0004 \u0005[גינות]\u0006 המצויות בתוך העיר, \u0003שנאמר: \"שלחיך פרדס רמונים\"\u0004 (שיר השירים ד, י), \u0003אבל באגי לא מיזדבני\u0004 \u0005[שדות אינם נמכרים].\u0006 \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003רבן שמעון בן גמליאל למימר\u0004 \u0005[לומר]\u0006 כי \u0003אפילו באגי נמי מזדבני\u0004 \u0005[שדות גם כן נמכרים].\u0006 זו היתה לשון אחת של הדיון.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 זאת בלשון אחרת: \u0003סברוה\u0004 \u0005[היו סבורים\u0006 לומר בהלכה זו\u0005]:\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"שלחין\"\u0004 — \u0003גינוניאתא\u0004 \u0005[גינות];\u0006 ומעתה, \u0003בשלמא למאן דאמר באגי\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר\u0006 שסנטר הוא \u0005שדות],\u0006 \u0003אמר\u0004 ה\u0003תנא קמא\u0004 \u0005[הראשון]:\u0006 \u0003גנונייתא מיזדבן, באגי לא מיזדבני\u0004 \u0005[הגינות נמכרות, השדות אינם נמכרים],\u0006 \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003רבן שמעון בן גמליאל למימר\u0004 \u0005[לומר]\u0006 כי \u0003אפילו באגי מיזדבני\u0004 \u0005[שדות נמכרים]\u0006 יחד עם העיר,"],["\u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שסנטר הוא \u0003בר מחווניתא, אמר\u0004 ה\u0003תנא קמא\u0004 \u0005[הראשון]:\u0006 \u0003גינונייתא\u0004 \u0005[גינות],\u0006 \u0003ומהדר ליה\u0004 \u0005[ומשיב לו]\u0006 \u0003רבן שמעון בן גמליאל: בר מחווניתא?!\u0004 ומשיבים: \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 כי \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"שלחין\"\u0004 — \u0003גינונייתא\u0004 \u0005[גינות]?\u0006 \u0003לא, מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"שלחין\"\u0004 — \u0003בגי\u0004 \u0005[שדות],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ושלח מים על פני חוצות\"\u0004 (איוב ה, ו), ודווקא הם נמכרים עם העיר לדעת התנא הראשון, \u0003אבל בר מחווניתא\u0004 — \u0003לא מזדבן\u0004 \u0005[נמכר],\u0006 \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003רבן שמעון בן גמליאל למימר\u0004 \u0005[לומר]:\u0006 \u0003אפילו בר מחווניתא נמי מזדבן\u0004 \u0005[גם כן נמכר].\u0006","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 ראיה לדבר ממה ששנינו בברייתא, \u0003ר' יהודה אומר: סנטר אינו מכור, אנקולמוס\u0004 (עבד שהוא סופר העיר) \u0003מכור; מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003מ\u0004תוך ש\u0003אנקולמוס\u0004 הוא \u0003גברא\u0004 \u0005[איש],\u0006 \u0003סנטר\u0004 הוא \u0003נמי גברא\u0004 \u0005[גם כן איש]!\u0006 ודוחים: \u0003מידי איריא\u0004 \u0005[האם שייכים\u0006 הדברים\u0005]?\u0006 \u0003הא כדאיתא והא כדאיתא\u0004 \u0005[זה כמו שהוא וזה כמו שהוא],\u0006 וסנטר הוא שדה ולא שומר השדה.","ושואלים: \u0003ומי מצית אמרת הכי\u0004 \u0005[והאם יכול אתה לומר כך]\u0006 שלדעת ר' יהודה שדות אינם נמכרים, \u0003והא קתני סיפא\u0004 \u0005[והרי שנינו בסופה]\u0006 של אותה ברייתא: \u0003אבל\u0004 כשמוכר את העיר לא מכר לו \u0003לא\u0004 את \u0003שייריה, ולא\u0004 את \u0003בנותיה,\u0004 כפרים שיש להם קשר לעיר, \u0003ולא חורשין\u0004 (חורשות) \u0003המוקצין\u0004 השייכים ומיועדים \u0003לה, ולא ביברין\u0004 מקומות מגודרים \u0003של חיה ושל עופות ושל דגים; ואמרינן\u0004 \u0005[ואמרנו,\u0006 הסברנו\u0005]:\u0006 \u0003מאי\u0004 \u0005[מה\u0006 הם\u0005]\u0006 \u0003\"שייריה\"?\u0004 — \u0003ביזלי,\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003ביזלי? אמר ר' אבא: פיסקי בגי\u0004 \u0005[חלקי השדה],\u0006 שיש הפסק בינם ובין השדות העיקריים. ומעתה, יש לדייק: \u0003פיסקי בגי\u0004 \u0005[חלקי השדות]\u0006 \u0003הוא\u0004 ש\u0003לא מזדבני\u0004 \u0005[נמכרים],\u0006 \u0003הא בגי\u0004 \u0005[הרי שדות]\u0006 \u0003עצמן\u0004 — \u0003מזדבני\u0004 \u0005נמכרים]!\u0006","ואומרים: \u0003איפוך\u0004 \u0005[הפוך]\u0006 ואמור ש\u0003ר' יהודה אומר: סנטר\u0004 שלפי הבנה זו משמעו שדות — \u0003מכור, אנקולמוס\u0004 — \u0003אינו מכור.\u0004","ושואלים: \u0003ומי מצית אמרת\u0004 \u0005[והאם יכול אתה לומר]\u0006 ש\u0003ר' יהודה כרבן שמעון בן גמליאל סבירא ליה\u0004 \u0005[סבור הוא]\u0006 עד שאתה מוכיח מדבריו על דברי רבן שמעון בן גמליאל? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' יהודה כרבנן סבירא ליה\u0004 \u0005[כ\u0006דעת \u0005חכמים סבור הוא]!\u0006 \u0003דקתני סיפא\u0004 \u0005[ששנינו בסופה]\u0006 של אותה ברייתא המביאה את דברי ר' יהודה: \u0003אבל לא\u0004 מכר את \u0003שייריה ולא\u0004 את \u0003בנותיה, ואילו רבן שמעון בן גמליאל האמר\u0004 \u0005[הרי אמר]:\u0006 \u0003מכר את העיר\u0004 — \u0003מכר\u0004 את \u0003בנותיה, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003המוכר את העיר\u0004 — \u0003לא מכר את בנותיה, רבן שמעון בן גמליאל אומר: המוכר את העיר\u0004 — \u0003מכר\u0004 את \u0003בנותיה!\u0004","ודוחים ואומרים: מכאן אין ראיה, אפשר לומר ש\u0003ר' יהודה סבר ליה כוותיה בחדא, ופליג עליה בחדא\u0004 \u0005[סבור כמותו ב\u0006דבר \u0005אחד\u0006 — ששדות העיר מכורים, \u0005וחולק עליו באחד\u0006 — שלדעת ר' יהודה בנותיה לא מכורות\u0005].\u0006","שנינו בברייתא בין הדברים שאינם נמכרים בכלל העיר: \u0003ולא ביברין של חיה ושל עופות ושל דגים.\u0004 \u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003היו לה\u0004 לעיר \u0003בנות\u0004 (כפרים סמוכים) — \u0003אין נמכרות עמה; היה לה חלק אחד בים וחלק אחד ביבשה,\u0004 או \u0003ביברים של חיה ושל עופות ושל דגים\u0004 — \u0003הרי אלו נמכרים עמה!\u0004","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 שיש לחלק בין מקרים שונים: \u0003הא דנגיח קאיהי לגו\u0004 \u0005[זה שמופנה פתחם לפנים]\u0006 כלפי העיר, הרי הם בכלל העיר, \u0003והא דנגיח קאיהי לבר\u0004 \u0005[וזה שמופנה פתחם לחוץ],\u0006 שבכגון זה אינם בכלל העיר. ומקשים: \u0003והא קא תני\u0004 \u0005[והרי שנה]:\u0006 \u0003ולא\u0004 מכר \u0003את חורשין המוקצין לה,\u0004 משמע שפתוחים כלפי העיר, ובכל זאת אינם נמכרים עימה! ומשיבים: \u0003אימא\u0004 \u0005[אמור]\u0006 לא \"המוקצין לה\", אלא: \u0003המוקצין הימנה,\u0004 כלומר, אלה הנמצאים מרוחקים ממנה ופתחיהם לחוץ.","\u0003המוכר את השדה\u0004 — \u0003מכר את האבנים\u0004 שבשדה \u0003שהם לצרכה\u0004 של השדה, \u0003ואת הקנים שבכרם שהם לצרכו\u0004 של הכרם, \u0003ואת התבואה שהיא מחוברת לקרקע, ואת חיצת\u0004 (מחיצה, קבוצת) \u0003הקנים שהיא פחותה\u0004 בשיעורה \u0003מבית רובע, ואת השומירה\u0004 (סוכת שומרים) \u0003שאינה עשויה בטיט, ואת החרוב\u0004 הצעיר \u0003שאינו מורכב\u0004 עדיין, \u0003ואת בתולת השקמה,\u0004 כלומר, שקמה שעדיין לא קצצו את ענפיה, שהיא צעירה וקטנה.","\u0003אבל לא מכר\u0004 בכלל השדה \u0003לא את האבנים שאינן לצרכה, ולא את הקנים שבכרם שאינן לצרכו, ולא את התבואה שהיא תלושה מן הקרקע;\u0004 ו\u0003בזמן שאמר לו: \"היא וכל מה שבתוכה\u0004 אני מוכר לך \u0003\"\u0004— \u0003הרי כולן מכורין; בין כך ובין כך,\u0004 אפילו אמר שמוכר כל מה שבתוכה — \u0003לא מכר לא את חיצת הקנים שהיא\u0004 בשטח זריעה של \u0003בית רובע\u0004 או יותר, שקובעת רשות לעצמה, \u0003ולא את השומירה שהיא עשויה בטיט, ולא את החרוב המורכב, ולא את סדן השקמה\u0004 שכל אלה חשובים הם, ויש להם שם לעצמם, ואינם נכללים במכירת השדה."],["שנינו במשנה שהמוכר את השדה מכר את האבנים שהן לצרכה, ומבארים: \u0003מאי\u0004 \u0005[מה\u0006 הן\u0005]\u0006 \u0003\"אבנים שהן לצרכה\"? הכא תרגימו\u0004 \u0005[כאן,\u0006 בבבל, \u0005תרגמו,\u0006 הסבירו\u0005]:\u0006 \u0003אבני דאכפא\u0004 \u0005[אבנים של האלומות\u0006 הנמצאות בשדה\u0005]\u0006 שמניחים אותן על האלומות, כדי שלא יתפזרו ברוח. \u0003עולא אמר:\u0004 הכוונה היא \u0003אבנים הסדורות\u0004 כדי \u0003ל\u0004בנות בהן \u0003גדר\u0004 לשדה. ומקשים: \u0003והא תני\u0004 \u0005[והרי שנה]\u0006 \u0003ר' חייא: אבנים צבורות לגדר,\u0004 ומשמע: כגל של אבנים, אף שאינן מסודרות! ומשיבים: \u0003תני\u0004 \u0005[שנה\u0006 בדבריו\u0005]:\u0006 \u0003סדורות\u0004 לגדר. וחוזרים ומפרשים ביתר פירוט את הדעות.","לפי מה ש\u0003הכא תרגימו\u0004 \u0005[כאן תרגמו,\u0006 הסבירו\u0005]\u0006 שהן \u0003אבני דאכפא\u0004 \u0005[האלומות],\u0006 הרי \u0003ל\u0004דעת \u0003ר' מאיר\u0004 הסבור (ראה להלן בבא בתרא עח,ב) כי בכלל מכירה של מקום גם כל הדברים הנחוצים לשימוש אותו מקום, הכוונה כאן לאבנים \u0003דמתקנן אף על גב דלא מחתן\u0004 \u0005[שמתוקנות\u0006 לצורך של שמירת האלומות \u0005אף על פי שאינן מונחות\u0006 עדיין עליהן\u0005],\u0006 ואילו \u0003לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים,\u0006 סתם משנתנו\u0005]\u0006 — \u0003הוא\u0004 דווקא \u0003דמחתן\u0004 \u0005[שמונחות].\u0006","\u0003ול\u0004דעת \u0003עולא\u0004 ש\u0003אמר: אבנים הסדורות לגדר,\u0004 הרי \u0003ל\u0004דעת \u0003ר' מאיר\u0004 נמכרו בכלל השדה אבנים \u0003דמתקנן אף על גב דלא סדרן\u0004 \u0005[שמתוקנות אף על פי שאינן מסודרות]\u0006 בשורה, \u0003לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים]\u0006 — \u0003הוא\u0004 דווקא \u0003דסדרן\u0004 \u0005[שמסודרות].\u0006","וממשיכים לבאר את המשנה. שנינו בין הדברים הנמכרים בכלל השדה: \u0003ואת הקנים שבכרם שהן לצרכו.\u0004 ותוהים: \u0003קנים מאי עבידתייהו\u0004 \u0005[מה מעשיהם]\u0006 מה עניינם לכרם? \u0003אמרי דבי\u0004 \u0005[אומרים בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי:\u0004 הכוונה היא ל\u0003קנים המחולקין\u0004 בראשיהם \u0003שמעמידים תחת הגפנים\u0004 כדי שענפי הגפנים ישענו עליהם, \u0003ל\u0004דעת \u0003ר' מאיר\u0004 מדובר בקנים \u0003דמשפיין אף על גב דלא מוקמן\u0004 \u0005[שהם משופים,\u0006 מתוקנים, לצורך זה \u0005אף על פי שאינם מועמדים]\u0006 במקומם, \u0003לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים]\u0006 — \u0003הוא\u0004 דווקא \u0003דמוקמן\u0004 \u0005[שמועמדים]\u0006 כבר.","וממשיכים לבאר את מה ששנינו במשנה: \u0003ואת התבואה המחוברת לקרקע וכו'.\u0004 ומעירים: \u0003ואף על גב דמטאי למיחצד\u0004 \u0005[ואף על פי שהגיע\u0006 זמנה \u0005להיקצר],\u0006 מכל מקום כיון שלא נקצרה, עדיין דינה כקרקע ובכלל מכירתה היא. עוד שנינו במשנה: \u0003ואת חיצת\u0004 (מחיצה, קבוצת) \u0003הקנים שפחותה מבית רובע.\u0004 ומעירים: \u0003ואף על גב דאלימי\u0004 \u0005[ואף על פי ש\u0006הקנים הללו \u0005עבים],\u0006 מכל מקום הם בטלים לשדה.","שנינו במשנה: \u0003ואת השומירה שאינה עשויה בטיט.\u0004 ומעירים: \u0003אף על גב דלא קביעא בארעא\u0004 \u0005[אף על פי שאינה קבועה בקרקע]\u0006 ואפשר לטלטל אותה, מכל מקום הואיל ואינה עשויה בטיט — אינה חשובה לעצמה, והיא נחשבת כחלק מן השדה. ועוד שנינו: \u0003ואת החרוב שאינו מורכב, ואת בתולת השקמה.\u0004 ומעירים: \u0003אף על גב דאלימי\u0004 \u0005[אף על פי ש\u0006הם גדולים ו\u0005עבים],\u0006 מכל מקום הואיל ולא הגיעו לשלב ההרכבה (בחרוב) או הקציצה (בשקמה) — רואים אותם כחלק מהקרקע.","ומפרשים את חלקה השני של המשנה: \u0003אבל לא מכר את האבנים שאינן לצרכה.\u0004 ומסבירים: לפירוש שאלו הן אבנים של אלומות, הרי \u0003ל\u0004דעת \u0003ר' מאיר\u0004 אלו הן אבנים \u0003דלא מתקנן\u0004 \u0005[שאינן מתוקנות],\u0006 ואילו \u0003לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים]\u0006 אף האבנים המתוקנות, כל \u0003דלא מחתן\u0004 \u0005[שאינן מונחות]\u0006 אינן מכורות.","\u0003ול\u0004דעת \u0003עולא\u0004 ש\u0003אמר:\u0004 שאבנים אלה הם \u0003אבנים הסדורות לגדר, ל\u0004דעת \u0003ר' מאיר\u0004 — \u0003דלא מתקנן\u0004 \u0005[שאינן מתוקנות],\u0006 \u0003לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים]\u0006 \u0003דלא סדרן\u0004 \u0005[שאינן מסודרות]\u0006 אף שהן מתוקנות לכך.","ועוד שנינו במשנה: \u0003ולא את הקנים\u0004 \u0003שבכרם שאינן לצרכו.\u0004 ומסבירים: \u0003ל\u0004דעת \u0003ר' מאיר\u0004 — \u0003דלא משפיין\u0004 \u0005[שאינם משופים,\u0006 מתוקנים\u0005],\u0006 \u0003לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים]\u0006 — \u0003דלא מוקמן\u0004 \u0005[שאינם מועמדים\u0006 במקומם\u0005].\u0006 שנינו: \u0003ולא את התבואה התלושה מן הקרקע.\u0004 ומעירים: \u0003ואף על גב דצריכא לארעא\u0004 \u0005[ואף על פי שצריכה לקרקע]\u0006 להיות מונחת בשדה, להתייבש ולהתאוורר.","ועוד שנינו: \u0003ולא\u0004 מכר \u0003את חיצת הקנים שהיא בית רובע.\u0004 ומעירים: \u0003ו\u0004החידוש הוא \u0003אף על גב דקטיני\u0004 \u0005[אף על פי ש\u0006הם \u0005דקים],\u0006 מכל מקום הואיל והם תופשים שטח בית רובע — הם נחשבים כרשות לעצמם. ובענין זה \u0003אמר ר' חייא בר אבא אמר ר' יוחנן: לא חיצת הקנים בלבד\u0004 נחשבת כרשות לעצמה ואינה נכללת במכירה, \u0003אלא אפילו ערוגה קטנה של בשמים\u0004 שאין בשטחה בית רובע, \u0003ו\u0004אולם \u0003יש לה שם בפני עצמה\u0004 — \u0003אינה נמכרת עמה\u0004 עם השדה. \u0003אמר רב פפא: והוא,\u0004 כוונת הדברים היא, \u0003דקרו\u0004 \u0005[שקורים]\u0006 \u0003לה \"וורדא דפלניא\"\u0004 \u0005[\"בית וורדים של פלוני\"],\u0006 שבכך היא קובעת שם לעצמה.","שנינו: \u0003ולא\u0004 מכר את \u0003השומירה העשויה בטיט.\u0004 ומעירים: \u0003ואף על גב דמחברא בארעא\u0004 \u0005[ואף על פי ש\u0006היא \u0005מחוברת לקרקע]\u0006 מכל מקום הריהי נחשבת כבנין לעצמו, שאינו חלק מן השדה. ועוד שנינו: \u0003ולא את חרוב המורכב ולא סדן השקמה.\u0004 ומעירים: \u0003ואף על גב דקטיני\u0004 \u0005[ואף על פי ש\u0006הם \u0005דקים],\u0006 מכל מקום הם כבר נחשבים כיחידה לעצמה.","אגב ענין זה של שומירה המחוברת, מביאים מה ש\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' אלעזר\u0004 בענין מכירה של בית: \u0003מלבנות של פתחים\u0004 (מסגרות, מזוזות ומשקוף מעץ), \u0003מהו\u0004 דינם? האם הם נמכרים יחד עם הבית, או לא? ומסבירים את השאלה: \u0003היכא דמחברי בטינא\u0004 \u0005[במקום ש\u0006הם \u0005מחוברים\u0006 לבית \u0005בטיט]\u0006 \u0003לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 השאלה — \u0003דהא מחבר\u0004 \u0005[\u0006\u0005שהרי מחוברים\u0006 הם\u0005],\u0006 \u0003כי תיבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 השאלה — הרי זה באופן \u0003דנקיטי בסיכי\u0004 \u0005[ש\u0006הם רק \u0005אחוזים ביתדות עץ קטנות],\u0006 ואם כן \u0003מאי\u0004 \u0005[מה]\u0006 הדין? לשאלה זו לא נמצאה תשובה ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","ובענין דומה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' זירא: מלבנות של חלונות, מהו\u0004 דינם במכירת הבית? \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]:\u0006 \u0003לנוי בעלמא\u0004 \u0005[סתם]\u0006 \u0003הוא דעבידי\u0004 \u0005[שעשויים]\u0006 ואינם נמכרים עם הדירה, ולכן יכול המוכר להוציא אותם וללוקחם, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון דמחברי\u0004 \u0005[ש\u0006הם \u0005מחוברים\u0006 לחלון\u0005]\u0006 — \u0003מחברי\u0004 \u0005[מחוברים]?\u0006 גם לשאלה זו לא נמצאה תשובה ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 אף היא במקומה.","וכן \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה: מלבנות של כרעי המטה,\u0004 שמונחים מתחת לכרעי המיטה, כדי שלא יתקלקלו ברטיבות, \u0003מהו?\u0004 ומסבירים את השאלה: \u0003כל היכא דמטלטלי בהדה\u0004 \u0005[כל מקום ש\u0006הם \u0005מיטלטלים יחד איתה]\u0006 \u0003לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 השאלה — \u0003דהא מטלטלי\u0004 \u0005[שהרי מיטלטלים\u0006 הם\u0005],\u0006 \u0003כי תיבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 השאלה, הרי זה \u0003היכא דלא מטלטלי\u0004 \u0005[במקום שאינם מיטלטלים],\u0006 אם כן \u0003מאי\u0004 \u0005[מה]\u0006 הדין? גם לשאלה זו לא נמצאה תשובה ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 אף היא במקומה.","שנינו במשנה בין הדברים שאינם נמכרים בכלל השדה: \u0003\"ולא את חרוב המורכב ולא סדן השקמה\" וכו'.\u0004"],["ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 מהו המקור בכתוב לדבר זה, שחרוב המורכב וסדן השקמה אינם נמכרים בכלל השדה? \u0003אמר רב יהודה אמר רב,\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ויקם שדה עפרון אשר במכפלה\u0004 אשר לפני ממרא השדה והמערה אשר בו, וכל העץ אשר בשדה אשר בכל גבולו סביב. לאברהם למקנה\u0003\"\u0004 (בראשית כג, יז–יח), לומר: \u0003מי שצריך לגבול סביב\u0004 שאינו ניכר ואינו עומד בפני עצמו, הריהו נמכר בכלל השדה, \u0003יצאו אלו,\u0004 החרוב המורכב וסדן השקמה, \u0003שאין צריכין לגבול סביב,\u0004 משום שהם ניכרים בפני עצמם. \u0003אמר רב משרשיא: מכאן,\u0004 מפסוק זה לגבי הגבול, מקור \u0003ל\u0004ענין סימון \u0003מצרים מן התורה.\u0004","\u0003אמר רב יהודה: האי מאן דמזבן ארעא לחבריה\u0004 \u0005[מי שמוכר קרקע לחבירו],\u0006 \u0003צריך למכתב ליה\u0004 \u0005[לכתוב לו]:\u0006 \u0003\"קני\u0004 \u0005[קנה]\u0006 \u0003לך דיקלין ותאלין והוצין וציצין\u0004 \u0005[דקלים ותמרים וענפים ושתילים]\u0006 \u0003\".\u0004 \u0003ואף על גב דכי\u0004 \u0005[ואף על פי שכאשר]\u0006 \u0003לא כתב ליה הכי\u0004 \u0005[לו כך]\u0006 בכל זאת \u0003קני\u0004 \u0005[קונה]\u0006 את כולם, כפי שעולה ממשנתנו, שרק חרוב המורכב וסדן השקמה אינם נמכרים בכלל השדה, \u0003אפילו הכי\u0004 \u0005[כך]\u0006 — \u0003שופרא דשטרא\u0004 \u0005[יפוי השטר]\u0006 \u0003הוא\u0004 שכותב בבירור, כדי שלא יהיה מקום למחלוקת.","אם \u0003אמר ליה\u0004 \u0005[לו]\u0006 המוכר לקונה: \u0003\"ארעא ודיקלי\u0004 \u0005[קרקע ודקלים]\u0006 מוכר אני לך \u0003\"\u0004— \u0003חזינן\u0004 \u0005[רואים אנו],\u0006 \u0003אי אית ליה\u0004 \u0003דיקלי\u0004 \u0005[אם יש לו דקלים]\u0006 — \u0003יהיב ליה תרי דיקלי\u0004 \u0005[נותן לו שני דקלים]\u0006 שהם מיעוט רבים, \u0003ואי לית ליה\u0004 \u0005[ואם אין לו]\u0006 דקלים — \u0003זבין ליה תרי דיקלי\u0004 \u0005[קונה לו שני דקלים]\u0006 במקום אחר. \u0003ואי משעבדי\u0004 \u0005[ואם\u0006 יש לו דקלים, אבל \u0005משועבדים\u0006 הם לאחר\u0005]\u0006 — \u0003פריק ליה תרי דיקלי\u0004 \u0005[פודה\u0006 ונותן \u0005לו שני דקלים].\u0006","אם אמר לו המוכר: \u0003\"ארעא בדיקלי\u0004 \u0005[קרקע בדקלים]\u0006 אני מוכר לך \u0003\"\u0004— \u0003חזינן\u0004 \u0005[רואים אנו],\u0006 \u0003אי אית\u0004 \u0005[אם יש]\u0006 \u0003בה דיקלי\u0004 \u0005[דקלים]\u0006 בקרקע — \u0003יהיב ליה\u0004 \u0005[נותן לו],\u0006 \u0003ואי לאו\u0004 \u0005[ואם לא]\u0006 — \u0003מקח טעות הוא.\u0004 אם אמר לו: \u0003\"ארעא בי דיקלי\u0004 \u0005[קרקע של דקלים]\u0006 אני מוכר לך \u0003\"\u0004— \u0003לית ליה דיקלי\u0004 \u0005[אין לו דקלים]\u0006 לקונה, ואם אין דקלים בשדה אין זה מיקח טעות, ומדוע? —קרקע \u0003דחזיא לדיקלי קאמר ליה\u0004 \u0005[שראויה לדקלים אמר לו]\u0006 ואין בלשון זו דקלים ממש. ועוד, אם \u0003אמר ליה\u0004 \u0005[לו]\u0006 המוכר שהוא מוכר לו את הקרקע \u0003לבר מדיקלא פלניא\u0004 \u0005[חוץ מדקל פלוני]\u0006 — \u0003חזינן\u0004 \u0005[רואים אנו],\u0006 \u0003אי דיקלא טבא\u0004 \u0005[אם דקל טוב]\u0006 \u0003הוא\u0004 — \u0003שיורי שייריה\u0004 \u0005[שיור שייר אותו]\u0006 לעצמו, ולא מכרו בכלל השדה, \u0003אי דיקלא בישא\u0004 \u0005[אם דקל רע]\u0006 \u0003הוא\u0004 — \u0003כל שכן הנך\u0004 \u0005[אלה\u0006 האחרים\u0005]\u0006","שכולם שייר לעצמו. אם \u0003אמר ליה\u0004 \u0005[לו]\u0006 שמוכר לו את הקרקע \u0003לבר מאילני\u0004 \u0005[חוץ מאילנות],\u0006 \u0003אי אית ליה אילני\u0004 \u0005[אם יש לו אילנות\u0006 בשדה\u0005],\u0006 כלומר, עצים שונים, כגון עצי זית ותאנה — מכר לו את השדה \u0003לבר מאילני\u0004 \u0005[חוץ מאילנות].\u0006 \u0003אי אית ליה דיקלי\u0004 \u0005[אם יש לו\u0006 רק \u0005דקלים]\u0006 ולא אילנות אחרים — כוונתו היתה \u0003לבר מדיקלי\u0004 \u0005[\u0006\u0005חוץ מדקלים],\u0006 אף על פי שאין קוראים להם אילנות סתם. וכן \u0003אי אית ליה גופני\u0004 \u0005[אם יש לו\u0006 רק \u0005גפנים]\u0006 — \u0003לבר מגופני\u0004 \u0005[חוץ מגפנים].\u0006","אם היו באותו שדה \u0003אילני וגופני\u0004 \u0005[אילנות וגפנים]\u0006 הרי מכר לו כל הקרקע ואף הגפנים, \u0003לבר מאילני\u0004 \u0005[חוץ מהאילנות]\u0006 שאותם הוציא מכלל המכר. וכן אם יש לו באותו שדה \u0003אילני ודיקלי\u0004 \u0005[אילנות ודקלים]\u0006 — הרי זה מכר הכל \u0003לבר מאילני\u0004 \u0005[חוץ מהאילנות].\u0006 אם אין לו אילנות אבל יש לו \u0003גופני ודיקלי\u0004 \u0005[גפנים ודקלים]\u0006 — \u0003לבר מגופני\u0004 \u0005[חוץ מהגפנים]\u0006 שאותם שייר לעצמו, והדקלים נמכרים עם השדה.","\u0003אמר רב:\u0004 אם מכר לו שדה ואמר שאין האילנות בכלל, הרי \u0003כל\u0004 אילן שהוא גדול עד \u0003שעולין לו בחבל\u0004 כדי להוריד פירותיו — \u0003הוי\u0004 \u0005[הרי זה]\u0006 \u0003שיור\u0004 ואינו נקנה בכלל השדה. ו\u0003כל שאין עולין לו בחבל\u0004 — \u0003לא הוי\u0004 \u0005[אין זה]\u0006 \u0003שיור,\u0004 והריהו נמכר עם השדה."],["\u0003ודייני גולה אמרי\u0004 \u0005[אומרים]:\u0006 \u0003כל\u0004 אילן \u0003שהעול\u0004 שעל השוורים החורשים \u0003כובשו\u0004 (מכופף אותו) תוך כדי החרישה והאילן אינו מעכבו — \u0003לא הוי\u0004 \u0005[אינו]\u0006 \u0003שיור,\u0004 שאילן שאינו חשוב הוא, \u0003כל שאין העול כובשו\u0004 — \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003שיור.\u0004 ומעירים: \u0003ולא פליגי\u0004 \u0005[ואין\u0006 הם \u0005חלוקים\u0006 בהלכה\u0005],\u0006 כי \u0003הא\u0004 \u0005[זה]\u0006 שאמר רב כל שעולים לו בחבל — מדובר \u0003בדיקלי\u0004 \u0005[בדקלים],\u0006 שאם היו גבוהים כל כך אינם נמכרים, \u0003הא\u0004 \u0005[זה]\u0006 שאמרו דייני הגולה — \u0003באילני\u0004 \u0005[באילנות\u0006 אחרים\u0005].\u0006","ובאותו ענין ששנינו במשנתנו כי החרוב המורכב וסדן השקמה אינם נמכרים בכלל השדה, \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רב אחא בר הונא מרב ששת:\u0004 אם אמר לו מוכר השדה, לקונה: \u0003\"\u0004שדי מכורה לך \u0003חוץ מחרוב\u0004 מורכב \u0003פלוני\",\u0004 או שאמר לו \u0003\"חוץ מסדן\u0004 שקמה \u0003פלוני\",\u0004 והיו בשדה עוד חרובים מורכבים וסדני שקמה, \u0003מהו\u0004 הדין בכגון זה? ותוכן השאלה: האם התכוון המוכר לומר בייתור לשונו כי \u0003אותו חרוב הוא\u0004 ש\u0003לא קני\u0004 \u0005[קונה]\u0006 הקונה, \u0003הא\u0004 \u0005[אבל]\u0006 את \u0003שאר\u0004 ה\u0003חרובים קני\u0004 \u0005[\u0006הוא \u0005קונה],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 את \u0003שאר\u0004 ה\u0003חרובין נמי לא קני\u0004 \u0005[גם כן אינו קונה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב ששת בתשובה: \u0003לא קנה\u0004 אף את שאר החרובים.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 רב אחא על כך ממה ששנינו בברייתא: האומר \u0003\"\u0004שדי מכורה לך \u0003חוץ מחרוב פלוני\",\u0004 או שאמר לו \u0003\"\u0004שדי מכורה לך \u0003חוץ מסדן פלוני\"\u0004 — \u0003לא קנה; מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה היא שדווקא \u0003אותו חרוב הוא\u0004 ש\u0003לא קנה, הא\u0004 \u0005[אבל]\u0006 \u0003שאר חרובין קנה?\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא,\u0004 הכוונה היא ש\u0003אפילו שאר חרובין נמי\u0004 \u0005[גם כן]\u0006 \u0003לא קנה. תדע\u0004 שכן הוא כדבריי, ש\u0003אילו אמר ליה\u0004 \u0005[\u0006היה \u0005אומר לו]:\u0006 \u0003\"שדי מכורה לך חוץ משדה פלונית\u0004 הסמוכה לזו \u0003\",\u0004 האם תאמר גם כן שדווקא את השדה \u0003ההיא\u0004 \u0003הוא\u0004 ש\u0003לא קני\u0004 \u0005[קנה],\u0006 \u0003הא אחרנייתא קני\u0004 \u0005[אבל אחרות קונה]?\u0006 והרי בפירוש אמר שמוכר לו שדה מסויימת, ולא כל שדותיו! \u0003אלא\u0004 בוודאי אתה אומר ש\u0003לא קנה\u0004 את השדות האחרות, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בחרובים, \u0003לא קנה,\u0004 שאין מכירת השדה כוללת כלל חרובים.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 בלשון אחרת: \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רב אחא בר הונא מרב ששת:\u0004 מוכר שדה שאמר לקונה: \u0003\"\u0004שדי מכורה לך \u0003חוץ מחצי חרוב פלוני\", \"חוץ מחצי סדן פלוני\", מהו\u0004 הדין? ותוכן השאלה: במקרה כזה \u0003שאר חרובין ודאי לא קני\u0004 \u0005[קנה],\u0006 \u0003הא\u0004 \u0005[אבל]\u0006 \u0003מה ששייר באותו חרוב,\u0004 כלומר, המחצית שלא פירש המוכר שהוא משייר לעצמו — \u0003קני\u0004 \u0005[קנה],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003אפילו מה ששייר באותו חרוב נמי\u0004 \u0005[גם כן]\u0006 \u0003לא קני\u0004 \u0005[קנה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב ששת בתשובה: \u0003לא קני\u0004 \u0005[קנה]\u0006 אף את מה ששייר באותו חרוב.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 רב אחא על כך ממה ששנינו בברייתא: \u0003\"חוץ מחצי חרוב פלוני\", \"חוץ מחצי סדן פלוני\"\u0004 — \u0003שאר חרובין לא קנה; מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה שדווקא \u0003שאר חרובין הוא\u0004 ש\u0003לא קנה, הא\u0004 \u0005[אבל]\u0006 \u0003מה ששייר באותו חרוב קנה?\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא\u0004 זו הכוונה, אלא \u0003אפילו מה ששייר באותו חרוב נמי\u0004 \u0005[גם כן]\u0006 \u0003לא קנה. תדע\u0004 שכן הוא, ש\u0003אילו אמר ליה\u0004 \u0005[\u0006היה \u0005אומר לו]:\u0006 \u0003\"שדי מכורה לך חוץ מחצי שדה פלוני\",\u0004 וכי תאמר גם כן כי את \u0003ההוא\u0004 \u0005[אותו]\u0006 חצי שדה אחר \u0003הוא\u0004 ש\u0003לא קנה, הא אידך\u0004 \u0005[אבל\u0006 את החצי \u0005האחר]\u0006 של אותו שדה \u0003קנה? אלא לא קני\u0004 \u0005[קנה],\u0006 \u0003הכא נמי\u0004 \u0005[כך גם כן]\u0006 \u0003לא קני\u0004 \u0005[קנה].\u0006","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רב עמרם מרב חסדא: המפקיד\u0004 דברים מסויימים \u0003אצל חבירו בשטר\u0004 שכתוב בו בחתימת עדים שפלוני הפקיד ביד פלוני דברים אלה, \u0003ואמר לו\u0004 אחר כך הנפקד למפקיד: \u0003\"החזרתים לך\",\u0004 והשטר עדיין בידי המפקיד, \u0003מהו\u0004 הדין? וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]:\u0006 \u0003מיגו דאי בעי אמר\u0004 \u0005[מתוך שאם היה רוצה היה אומר]\u0006 \u0003\"נאנסו\",\u0004 נלקחו ממני באונס — \u0003מהימן\u0004 \u0005[נאמן],\u0006 \u0003השתא נמי מהימן\u0004 \u0005[עכשיו גם כן נאמן]\u0006 באומרו \"החזרתים\", שהרי אם רצונו לשקר — היה טוען שנלקחו ממנו באונס. \u0003או דלמא אמר ליה\u0004 \u0005[שמא יכול לומר לו]\u0006 המפקיד: אם אמנם החזרת לי, \u0003\"שטרך בידי מאי בעי\u0004 \u0005[מה\u0006 הוא \u0005רוצה]\u0006 \u0003\"?\u0004 כלומר, אם היית מחזיר, היית צריך לקחת ממני את השטר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא: \u0003מהימן\u0004 \u0005[נאמן]\u0006 הוא, משום ה\"מיגו\".","ושאל אותו רב עמרם: ובכל זאת, \u0003ולימא ליה\u0004 \u0005[ושיאמר לו]:\u0006 \u0003\"שטרך בידי מאי בעי\u0004 \u0005[מה\u0006 הוא \u0005רוצה]\u0006 \u0003\"?\u0004 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 \u0003וכי אמר ליה\u0004 \u0005[וכאשר אומר לו]\u0006 \u0003\"נאנסו\", מי מצי אמר ליה\u0004 \u0005[האם יכול\u0006 הוא \u0005לומר לו]:\u0006 \u0003\"שטרך בידי מאי בעי\u0004 \u0005[מה\u0006 הוא \u0005רוצה]\u0006 \u0003\"?\u0004 וכיון שכך, גם אם טוען \"החזרתי\" — אין יכול לטעון כנגדו מדוע לא לקח את השטר. \u0003אמר ליה\u0004 \u0005[לו]:\u0006"],["\u0003סוף סוף\u0004 גם \u0003כי אמר ליה\u0004 \u0005[כאשר\u0006 היה \u0005אומר לו]\u0006 \u0003\"נאנסו\" לאו\u0004 \u0005[האם לא]\u0006 \u0003שבועה בעי\u0004 \u0005[צריך\u0006 היה על כך\u0005]?\u0006 וכיצד אתה אומר שהוא נאמן לטעון שהחזירם בלי שבועה? אמר לו: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 לכך התכוונתי: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"נאמן\"?\u0004 — \u0003נאמן בשבועה.\u0004","ומציעים: \u0003לימא, בפלוגתא דהני תנאי\u0004 \u0005[האם לומר\u0006 שדבר זה שנוי \u0005במחלוקתם של תנאים אלה],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003שטר כיס\u0004 שהוא שטר המעיד שמסר אדם סכום כסף לחבירו בתורת \"עיסקא\" על מנת לחלוק ברווחים שהכסף המשותף יביא, \u0003היוצא על היתומים,\u0004 שנפטר מקבל הכסף ובעל הממון תובעו מן היתומים — \u0003דייני גולה אמרי\u0004 \u0005[אומרים]:\u0006 \u0003נשבע\u0004 התובע שלא הוחזר לו הכסף \u0003וגובה\u0004 את \u0003כולו, ודייני ארץ ישראל אמרי\u0004 \u0005[אומרים]:\u0006 \u0003נשבע\u0004 שלא קיבל, \u0003וגובה\u0004 רק \u0003מחצה\u0004 מן הסכום.","\u0003ו\u0004אנו מניחים \u0003דכולי עלמא אית להו דנהרדעי\u0004 \u0005[שהכל יש להם,\u0006 מקבלים, את שיטת חכמי \u0005נהרדעא],\u0006 \u0003דאמרי נהרדעי\u0004 \u0005[שאומרים\u0006 חכמי \u0005נהרדעא]:\u0006 \u0003האי עיסקא\u0004 \u0005[עיסקה זו]\u0006 שהאדם נותן כסף לחבירו כדי שיתעסק בכסף זה במסחר על מנת שיחלקו ברווחים — \u0003פלגא\u0004 \u0005[חציו]\u0006 נחשב כ\u0003מלוה\u0004 שאחריותו תמיד על הלווה, \u0003ופלגא\u0004 \u0005[וחציו]\u0006 נחשב כ\u0003פקדון,\u0004 שאם אירע בו אונס — פטור המקבל.","ולפי הנחה זו, על חלק המילווה סבורים כולם שנוטלו התובע מן היתומים (בשבועה) כדרך שהיה נוטלו מאביהם, אבל על חלק הפקדון \u0003מאי לאו בהא קא מיפלגי\u0004 \u0005[האם לא ב\u0006נושא \u0005זה הם חלוקים],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 דייני גולה, \u0005סבור]\u0006 ש\u0003מצי אמר ליה\u0004 \u0005[יכול לומר לו]\u0006 המפקיד לנפקד: \u0003\"שטרך בידי מאי בעי\u0004 \u0005[מה\u0006 הוא \u0005רוצה]\u0006 \u0003\",\u0004 ולכן לא האב ולא הבנים נאמנים לומר שהחזירו את חלק הפקדון, וגם אותו הוא גובה בנוסף לשטר המילווה, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 דייני ארץ ישראל, \u0005סבור]\u0006 כרב חסדא, שלדעתו \u0003לא אמרי\u0004 \u0005[אין אומרים]\u0006 טענה זו, ולכן אינו גובה הכל, אלא את חלק המילווה, שעל חלק הפקדון נאמן היה האב לטעון החזרתיו?","ודוחים: \u0003לא, דכולי עלמא אית להו\u0004 \u0005[לדעת הכל יש להם,\u0006 מקבלים את דברי\u0005]\u0006 \u0003רב חסדא,\u0004 ויכול היה האב לטעון \"החזרתי\", \u0003והכא בהא קמיפלגי\u0004 \u0005[וכאן בזה הם חלוקים],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 דייני גולה, \u0005סבור]:\u0006 \u0003אם איתא דפרעיה מימר הוה אמר\u0004 \u0005[אכן פרע לו היה אומר]\u0006 לבניו שפרע, ואם לא אמר כן — מן הסתם לא פרע. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 דייני גולה, \u0005סבור]:\u0006 \u0003אימור\u0004 \u0005[אמור,\u0006 יכול אתה לומר\u0005]:\u0006 \u0003מלאך המות הוא דאנסיה\u0004 \u0005[שאנס אותו],\u0006 כלומר, מת האיש לפני שהספיק לצוות לבניו את פרטי הדברים.","ובענין זה מביאים הלכה זו ש\u0003שלח רב הונא בר אבין: המפקיד\u0004 חפץ \u0003אצל חבירו בשטר, ו\u0004כשתבעו המפקיד שיחזירנו לו \u0003אמר לו\u0004 השומר: \u0003\"החזרתיו לך\"\u0004 — הרי זה \u0003נאמן, ושטר כיס היוצא על היתומין\u0004 — \u0003נשבע וגובה כולו.\u0004","ותוהים: \u0003תרתי\u0004 \u0005[שתים]\u0006 שתי הלכות הסותרות זו את זו? שהרי כפי שאמרנו, אם היה האב יכול לטעון \"החזרתי\", היינו טוענים טענה זו עבור היתומים! ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם],\u0006 \u0003דאם איתא דפרעיה מימר הוה אמר\u0004 \u0005[שאם אכן פרעו אומר היה]\u0006 לבניו שפרע, וכיון שלא אמר — מן הסתם לא פרע.","\u0003רבא אמר:\u0004 בענין זה של שטר כיס היוצא על היתומים \u0003הלכתא\u0004 \u0005[הלכה\u0006 היא\u0005]\u0006 ש\u0003נשבע וגובה מחצה,\u0004 כשיטת דייני ארץ ישראל. מסופר: שני דורות אחר כך \u0003אמר מר זוטרא: הלכתא\u0004 \u0005[הלכה]\u0006 בענין זה \u0003כדייני גולה.\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא למר זוטרא, הא\u0004 \u0005[הרי]\u0006 \u0003אמר רבא: נשבע וגובה מחצה! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנן\u0004 \u0005[אנו]\u0006 את ההלכה של \u0003דייני גולה\u0004"],["\u0003איפכא מתנינן לה\u0004 \u0005[ההיפך אנו שונים אותה],\u0006 כלומר, אנו גורסים שדייני גולה הם שפסקו שגובה מחצה, והוא כשיטת רבא.","כהמשך למשנה הקודמת (לעיל בבא בתרא סח,ב) אומרת המשנה כי המוכר את השדה, אף שאמר לקונה שמוכר לו כל מה שבתוכה, לא מכר \u0003לא את הבור ולא את הגת ולא את השובך, בין\u0004 שהיו \u0003חרבין\u0004 (לא פעילים), \u0003בין\u0004 שהיו \u0003ישובין,\u0004 שכל אלו אינם חלק מן השדה עצמו. \u0003וצריך\u0004 המוכר \u0003ליקח\u0004 (לקנות) \u0003לו דרך\u0004 מן הקונה, כדי שיוכל להגיע לאותם דברים ששייר לעצמו. אלו \u0003דברי ר' עקיבא,\u0004 שסבור שכל מוכר הריהו מוכר בעין יפה, ומשום כך מה שלא פירש שמשייר לעצמו — לא שייר, ולכן לא שייר לעצמו גם דרך לאלה, וצריך לקנות זכות זו מן הקונה. \u0003וחכמים אומרים: אינו צריך,\u0004 שכיון ששייר את כל אלה, ודאי שייר לעצמו גם דרך אליהם.","\u0003ומודה ר' עקיבא, בזמן שאמר לו\u0004 שהוא מוכר לו את השדה ופירש \u0003\"חוץ מאלו\",\u0004 \u0003שאינו צריך ליקח לו דרך,\u0004 שכיון שהוסיף בדבריו במפורש שהוא משייר את אלה, אף שממילא נשארו שלו — בוודאי התכוון גם לדרך אליהם. במקרה אחר, ש\u0003מכרן\u0004 את הבור ואת הגת, \u0003לאחר\u0004 והשדה שייר לעצמו — \u0003ר' עקיבא אומר:\u0004 הקונה \u0003אינו צריך ליקח לו דרך,\u0004 שהרי לשיטתו מוכר בעין יפה מוכר, ומכר לו גם דרך לאותם דברים. \u0003וחכמים אומרים: צריך ליקח לו דרך.\u0004","ומעירים: \u0003במה דברים אמורים\u0004 — \u0003במוכר, אבל בנותן מתנה\u0004 — ודאי \u0003נותן את כולה\u0004 וכל המצוי בה. וכן \u0003האחין\u0004 היורשים \u0003שחלקו\u0004 בנכסי אביהם, \u0003זכו בשדה,\u0004 כלומר, כל אחד כשזכה בשדה — \u0003זכו בכולה\u0004 בכל מה שמצוי בה. וכן \u0003המחזיק\u0004 העושה חזקה \u0003בנכסי הגר,\u0004 אם \u0003החזיק בשדה\u0004 — \u0003החזיק בכולה.\u0004","\u0003המקדיש את השדה\u0004 — \u0003הקדיש את כולה; ר' שמעון אומר: המקדיש את השדה\u0004 — \u0003לא הקדיש\u0004 את כל הדברים המצויים בשדה, \u0003אלא את החרוב המורכב ואת סדן השקמה,\u0004 אבל לא בור או גת וכיוצא בהם.","על ההבחנה האמורה במשנה בין מתנה למכר לענין שיור, שואלים: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003מכר ומאי שנא\u0004 \u0005[ו\u0006ב\u0005מה שונה]\u0006 \u0003מתנה? פירש יהודה בן נקוסא לפני רבי:\u0004 ההבדל הוא ש\u0003זה פירש וזה לא פירש.\u0004","ותוהים על כך: \u0003האי\u0004 \u0005[זה]\u0006 \u0003זה פירש וזה לא פירש,\u0004 הלוא \u0003זה לא פירש וזה לא פירש הוא,\u0004 שהרי בשני המקרים לא פירש המוכר מה הוא משייר! \u0003אלא\u0004 הכוונה היא כך: במכר, \u0003זה\u0004 הקונה \u0003היה לו לפרש\u0004 ולדרוש כל מה שאינו חלק בלתי נפרד מן השדה, ומשלא עשה כן — הפסיד. \u0003ו\u0004אילו במתנה \u0003זה\u0004 מקבל המתנה \u0003לא היה לו לפרש,\u0004 שאין זו דרך מקבלי מתנה.","מסופר, \u0003ההוא\u0004 \u0005[אחד]\u0006 ש\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003הבו ליה לפלניא ביתא\u0004 \u0005[תנו לו\u0006 במתנה \u0005לפלוני בית\u0006 שלי\u0005]\u0006 ש\u0003מחזיק\u0004 (מכיל) \u0003מאה גולפי\u0004 \u0005[חביות],\u0006 \u0003אשתכח דהוה\u0004 \u0005[נמצא שהיה]\u0006 ברשותו בית ש\u0003מחזיק מאה ועשרין\u0004 \u0005[ועשרים]\u0006 חביות, \u0003אמר מר זוטרא:\u0004 אין לו בבית אלא שטח שפירש, ולא את כל הבית, כי \u0003מאה אמר ליה\u0004 \u0005[לו],\u0006 \u0003מאה ועשרין לא אמר ליה\u0004 \u0005[לו].\u0006","\u0003רב אשי אמר: מי\u0004 \u0005[האם]\u0006 \u0003לא תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003במה דברים אמורים\u0004 — \u0003במוכר, אבל בנותן מתנה\u0004 — \u0003נותן את כולן? אלמא\u0004 \u0005[מכאן\u0006 אנו אומרים\u0005]\u0006 כי \u0003מאן דיהיב\u0004 \u0005[מי שנותן]\u0006 \u0003מתנה\u0004 — \u0003בעין יפה יהיב\u0004 \u0005[נותן],\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003מאן דיהיב\u0004 \u0005[מי שנותן]\u0006 \u0003מתנה\u0004 — \u0003בעין יפה יהיב\u0004 \u0005[נותן],\u0006 ולא דקדק בשיעורים, והתכוון לבית זה שמחזיק יותר ממאה חביות.","שנינו במשנה: \u0003המקדיש את השדה\u0004 — \u0003הקדיש\u0004 את כולה. \u0003אמר רב הונא, אף על גב דאמור רבנן\u0004 \u0005[אף על פי שאמרו חכמים]:\u0006 \u0003הקונה שני אילנות בתוך\u0004 שדהו \u0003של חבירו\u0004 — \u0003הרי זה לא קנה קרקע\u0004 אלא את האילנות בלבד, אם \u0003מכר קרקע\u0004 לחבירו \u0003ושייר שני אילנות לפניו\u0004 (לעצמו) — \u0003יש לו קרקע\u0004 לאילנות הללו. ומסבירים הלכה זו: \u0003ואפילו ל\u0004שיטת \u0003ר' עקיבא\u0004 ש\u0003אמר\u0004 ש\u0003מוכר בעין יפה מוכר\u0004 ולא משייר לעצמו, \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003בור ודות, דלא קא מכחשי בארעא\u0004 \u0005[שאינם מכחישים את הקרקע],\u0006 ולכן אינו רואה צורך להבטיח עצמו מפני טענות של קונה הקרקע. \u0003אבל אילנות דקא מכחשי בארעא\u0004 \u0005[שמכחישים את הקרקע]\u0006 ביניקתם ממנה,"],["\u0003אם איתא\u0004 \u0005[אכן]\u0006 נאמר ש\u0003לא שייר\u0004 המוכר קרקע לעצמו, \u0003לימא ליה\u0004 \u0005[שיאמר לו]\u0006 הקונה: \u0003\"עקור אילנך\u0004 \u0005[אילנותיך],\u0006 \u0003שקול וזיל\u0004 \u0005[קח ולך]\u0006","\u0003\",\u0004 שהרי הם יונקים מהקרקע שלי ומכחישים אותה בכך! ומאחר שהמוכר שייר לעצמו את האילנות, בוודאי התכוון להשאיר לעצמו גם את הקרקע השייכת לאילנות אלה. ומנסים להביא ראיה, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' שמעון אומר: המקדיש את השדה\u0004 — \u0003לא הקדיש\u0004 בכלל השדה \u0003אלא חרוב המורכב וסדן השקמה,\u0004 אבל לא שאר דברים המצויים בו ואינם חלק ממנו. \u0003ותני עלה\u0004 \u0005[ושנויה\u0006 ברייתא \u0005עליה],\u0006 \u0003אמר ר' שמעון: מה טעם\u0004 הוקדשו דווקא החרוב והשקמה? \u0003הואיל ויונקין משדה הקדש,\u0004 ואם לא הקדישם נמצא שהאילנות שלו יונקים מן ההקדש. אלא בוודאי בהכרח הם כלולים בתוך ההקדש כשהקדיש את השדה.","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 כדברי רב הונא, שכאשר משאיר לעצמו אילנות \u0003שיורי שייר\u0004 \u0005[משייר]\u0006 את הקרקע שסביבם כדי שיוכלו לינוק מקרקע שלו, מה טעמו של ר' שמעון? הלא \u0003כי קא ינקי\u0004 \u0005[כאשר הם יונקים]\u0006 \u0003—\u0004 \u0003מדנפשיה קא ינקי\u0004 \u0005[משלו הם יונקים]\u0006 מן הקרקע ששייר, ולא מן ההקדש!","ומשיבים: צריכים אנו לחזור מן ההנחה שרב הונא אמר דבריו לדעת הכל, אלא \u0003ר' שמעון\u0004 ש\u0003אמר\u0004 — \u0003כר' עקיבא\u0004 רבו הוא שאמר, שמוכר בעין יפה מוכר, ואינו משייר לעצמו יותר ממה שפירש, ואף לא קרקע לצורך החרוב, והוא הדין למקדיש. ולכן בהקדש — ודאי התכוון להקדיש גם את החרוב, כדי שלא יינק מקרקע של הקדש. \u0003ורב הונא\u0004 ש\u0003אמר\u0004 — \u0003כרבנן\u0004 \u0005[כ\u0006שיטת","\u0005חכמים]\u0006 הוא שאמר, שהמוכר בעין רעה מוכר, וכשמשייר דבר־מה בשדהו — משייר גם קרקע הנצרכת לו. ותוהים: \u0003כרבנן, פשיטא\u0004 \u0005[\u0006אם \u0005כ\u0006דעת \u0005חכמים פשוט\u0006 שכך הוא\u0005]\u0006 ומה צורך להשמיענו זאת! ומשיבים: יש חידוש בדבר, שכן \u0003נפקא מינה\u0004 \u0005[יוצא מכאן]\u0006 מדברי רב הונא, \u0003דאי נפלי הדר שתיל להו\u0004 \u0005[שאם\u0006 האילנות \u0005נופלים\u0006 או מתים יכול \u0005לחזור ולשתול אותם]\u0006 ואין אנו אומרים ששייר קרקע לצורך אילנות אלה שנפלו בלבד, אלא הקרקע שייכת לו לכל דבר."],["ושואלים: \u0003ומי מצית מוקמת לה\u0004 \u0005[והאם יכול אתה להעמיד אותה\u0006 את שיטת\u0005]\u0006 \u0003ר' שמעון כ\u0004דעת \u0003ר' עקיבא\u0004 שמוכר ומקדיש בעין יפה? \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הקדיש שלשה אילנות\u0004 הנטועים בצפיפות של \u0003מטע עשרה\u0004 אילנות \u0003לבית סאה\u0004 — \u0003הרי הקדיש\u0004 גם \u0003את הקרקע ואת האילנות\u0004 הקטנים \u0003שביניהם, לפיכך כשהוא פודה\u0004 אותם — אם הוא שדה אחוזה, \u0003פודה\u0004 את הקרקע ומה שיש בה לפי השיעור הכתוב בתורה — \u0003בית זרע חומר שעורים,\u0004 כלומר, מקום שבו זורעים כור של שעורים, \u0003בחמשים שקל כסף.\u0004","היה השטח היחסי של הקרקע \u0003פחות מכאן,\u0004 כלומר, שהם נטועים בצפיפות יתירה, \u0003או יותר על כן,\u0004 שהשטח בין האילנות גדול יותר, \u0003או שהקדישן בזה אחר זה\u0004 כל אחד מהם בנפרד — \u0003הרי זה לא הקדיש לא\u0004 את \u0003הקרקע ולא את האילנות שביניהם, לפיכך כשהוא פודה\u0004 — \u0003פודה את האילנות בשוויהן. ולא עוד, אלא אפילו הקדיש את האילנות\u0004 כשהם צפופים מדי, או מרווחים מדי, או בזה אחר זה, \u0003וחזר והקדיש\u0004 אחר כך \u0003את הקרקע,\u0004 ונמצא שעתה הכל ביד ההקדש, \u0003כשהוא פודה\u0004 — \u0003פודה\u0004 בנפרד \u0003את האילנות בשוויהן, וחוזר ופודה\u0004 את הקרקע לפי החשבון של \u0003בית זרע חומר שעורים בחמשים שקל כסף.\u0004","ונברר: \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]\u0006 הלכה זו? \u0003אי\u0004 \u0005[אם]\u0006 תאמר שהיא כדעת \u0003ר' עקיבא, הא\u0004 \u0005[הרי]\u0006 \u0003אמר: מוכר בעין יפה מוכר, וכל שכן מקדיש\u0004 בעין יפה מקדיש! \u0003אי רבנן\u0004 \u0005[אם\u0006 כשיטת \u0005חכמים],\u0006 \u0003הא אמרי\u0004 \u0005[הרי\u0006 הם \u0005אומרים\u0006 במשנה\u0005]:\u0006 \u0003מוכר הוא\u0004 זה ש\u0003בעין רעה מוכר, אבל מקדיש בעין יפה מקדיש,\u0004 שהמקדיש שדה — אף הבור והגת בכלל, ואם כן אף לשיטתם לא כך צריכה להיות ההלכה! \u0003אלא פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שהלכה זו דעת \u0003ר' שמעון\u0004 במשנתנו \u0003היא,\u0004 שאף המקדיש את השדה, אינו מקדיש עמו את הבור ואת הגת וכו';","\u0003ו\u0004אולם שיטת \u0003ר' שמעון אליבא דמאן\u0004 \u0005[לפי\u0006 שיטת \u0005מי\u0006 היא\u0005]?\u0006 \u0003אי אליבא\u0004 \u0005[אם לשיטת]\u0006 \u0003ר' עקיבא, הא\u0004 \u0005[הרי]\u0006 \u0003אמר: מוכר בעין יפה מוכר, וכל שכן מקדיש! אלא פשיטא\u0004 \u0005[פשוט]\u0006 ש\u0003אליבא דרבנן\u0004 \u0005[לפי\u0006 שיטת \u0005חכמים],\u0006 לפי ההנחה שלהם שהמוכר בעין רעה מוכר, \u0003וקא סבר\u0004 \u0005[ו\u0006אולם \u0005סבור]\u0006 \u0003ר' שמעון\u0004 שלא כשיטת חכמים, אלא: \u0003כי היכי\u0004 \u0005[כמו]\u0006 ש\u0003מוכר בעין רעה מוכר, מקדיש נמי\u0004 \u0005[גם כן]\u0006 \u0003בעין רעה מקדיש, ומשייר ארעא\u0004 \u0005[\u0006את \u0005הקרקע]\u0006 לעצמו;"],["\u0003ואלא קשיא\u0004 \u0005[קשה]\u0006 ממה שאמר ר' שמעון בחרוב ושקמה שהקדיש אותם בכלל השדה \u0003הואיל ויונקין משדה הקדש,\u0004 ומשמע מדבריו שהמקדיש בעין יפה מקדיש ואינו משייר לעצמו קרקע!","\u0003אלא\u0004 יש לומר כי \u0003ר' שמעון\u0004 שאמר במשנה שהקדיש חרוב ושקמה בכלל השדה, \u0003לדבריהם\u0004 ולפי שיטתם \u0003דרבנן\u0004 \u0005[של חכמים]\u0006 \u0003קאמר להו\u0004 \u0005[אמר להם],\u0006 ולא לפי שיטתו, וכך אמר: \u0003לדידי, כי היכי\u0004 \u0005[לשיטתי שלי כמו]\u0006 ש\u0003מוכר בעין רעה מוכר, מקדיש נמי\u0004 \u0005[גם כן]\u0006 \u0003בעין רעה מקדיש, ושיורי משייר\u0004 \u0005[ומשייר\u0006 לעצמו\u0005]\u0006 קרקע כדי יניקת האילנות, ולכן כשהקדיש את השדה אף חרוב ושקמה אינם בכלל ההקדש. \u0003לדידכו\u0004 \u0005[לשיטתכם]\u0006 שהמקדיש בעין יפה מקדיש, \u0003אודו לי מיהא\u0004 \u0005[הודו לי על כל פנים]\u0006 ש\u0003לא הקדיש אלא חרוב המורכב וסדן השקמה\u0004 משום שהם יונקים מקרקע הקדש, אבל לא דברים אחרים שאינם חלק מן השדה. \u0003ואמרי ליה רבנן\u0004 \u0005[ואמרו לו חכמים]:\u0006 \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 וכיון שמקדיש בעין יפה — מקדיש את כל הנמצא בשדה.","ושבים לדון בברייתא ממנה למדנו את שיטת ר' שמעון, ומקשים: \u0003במאי אוקימתא לה\u0004 \u0005[במה העמדת אותה]?\u0006 את הברייתא בענין הקדש — \u0003כר' שמעון,\u0004 ואולם \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005הסוף\u0006 של אותה ברייתא\u0005]:\u0006 \u0003ולא עוד, אלא אפילו הקדיש את האילנות וחזר והקדיש את הקרקע, כשהוא פודה\u0004 — \u0003פודה את האילנות בשוייהן, וחוזר ופודה\u0004 את הקרקע לפי חשבון \u0003בית זרע חומר שעורים בחמשים שקל כסף;\u0004","\u0003ואי\u0004 \u0005[ואם]\u0006 כשיטת \u0003ר' שמעון, ליזיל בתר\u0004 \u0005[שילך אחר]\u0006 מצב השדה בזמן ה\u0003פדיון וניפרקו אגב ארעייהו\u0004 \u0005[וייפדו אגב הקרקע שלהם],\u0006 שהרי בשעת פדיון גם הקרקע וגם העצים הם הקדש, \u0003דהא שמעינן ליה\u0004 \u0005[שהרי שמענו אותו]\u0006 את \u0003ר' שמעון דאזיל בתר\u0004 \u0005[ש\u0006הוא \u0005הולך אחר]\u0006 זמן ה\u0003פדיון!\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מנין ללוקח\u0004 (קונה) \u0003שדה מאביו והקדישה, ואחר כך מת אביו\u0004 ונמצא שהגיעה לו השדה כירושה, \u0003מנין שתהא לפניו\u0004 לענין פדיון \u0003כשדה אחוזה\u0004 ולא כשדה מקנה? \u0003תלמוד לומר\u0004 בענין שדה מקנה: \u0003\"ואם את שדה מקנתו אשר לא משדה אחזתו\u0004 יקדיש\u0003\"\u0004 (ויקרא כז, כב), לומר: אין הכתוב מדבר אלא באותה \u0003שדה שאין ראויה\u0004 בזמן שמקדיש אותה \u0003להיות שדה אחוזה, יצתה\u0004 (יצאה) \u0003זו שראויה\u0004 היתה \u0003להיות שדה אחוזה,\u0004 שהרי גם אם לא היה קונה אותה מאביו — זו היא אחוזת נחלתו. אלו \u0003דברי ר' יהודה ור' שמעון,\u0004 ואילו","\u0003ר' מאיר\u0004 לומד מפסוק זה הלכה שונה, וכך הוא \u0003אומר: מנין ללוקח שדה מאביו ומת אביו ואחר כך הקדיש, מנין שתהא לפניו כשדה אחוזה? תלמוד לומר: \"ואם את שדה מקנתו אשר לא משדה אחזתו\"\u0004 (ויקרא כז, כב), לומר: שדה מקנה היא \u0003שדה שאינה שדה אחוזה\u0004 בשעה שמקדיש אותה, \u0003יצתה זו שהיא\u0004 עכשיו, לאחר מות אביו, \u0003שדה אחוזה;\u0004","\u0003ואילו\u0004 לדעת \u0003ר' יהודה ור' שמעון, היכא\u0004 \u0005[במקום]\u0006 ש\u0003מת אביו ואחר כך הקדישה לא צריכי קרא\u0004 \u0005[אינם צריכים כתוב]\u0006 ללמד ששדה כזה הוא שדה אחוזה, \u0003כי אצטריך קרא\u0004 \u0005[כאשר הוצרך הכתוב]\u0006 — הרי זה \u0003היכא\u0004 \u0005[במקום]\u0006 ש\u0003הקדישה\u0004 כאשר היתה בידיו כשדה מקנה, \u0003ואחר כך מת אביו,\u0004 ויש לשאול:","\u0003מנא להו\u0004 \u0005[מניין להם]\u0006 זו? \u0003אי מהאי קרא\u0004 \u0005[אם מכתוב זה\u0006 בלבד\u0005],\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 כי כתוב זה לכמו שפירש \u0003ר' מאיר הוא דאתא\u0004 \u0005[שבא],\u0006 ולא כדבריהם, שהרי מן הפסוק עצמו אין הוכחה ברורה להסברם של החכמים. \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דאזלי בתר\u0004 \u0005[ש\u0006הם \u0005הולכים אחר]\u0006 זמן ה\u0003פדיון,\u0004 ובזמן הפדיון, לאחר שהאב מת, הרי זה שדה אחוזה שלו שנמצא ביד ההקדש?","\u0003אמר רב נחמן בר יצחק: לעולם בעלמא\u0004 \u0005[בכלל]\u0006 \u0003ר' יהודה ור' שמעון לא אזלי בתר\u0004 \u0005[הולכים אחר]\u0006 זמן ה\u0003פדיון,\u0004 ולא על בסיס סברה זו סמכו את פסקם. \u0003והכא קרא אשכחו ודרוש\u0004 \u0005[וכאן מקרא מצאו ודרשו]:\u0006 ש\u0003אם כן\u0004 כדברי ר' מאיר, \u0003לכתוב קרא\u0004 \u0005[שיאמר הכתוב]:\u0006 \u0003\"ואם את שדה מקנתו אשר לא אחזתו\", אי נמי\u0004 \u0005[או גם כן]\u0006 שיכתוב \u0003\"\u0004אשר לא \u0003שדה אחזתו\", מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 המילים \u0003\"אשר לא משדה אחזתו\"?\u0004 ומדייקים ממה שנאמר \"משדה\", מקצת השדה, לומר: \u0003את שאינה ראויה\u0004 כלל \u0003להיות שדה אחוזה\u0004 דינה כשדה מקנה, \u0003יצתה זו שראויה להיות שדה אחוזה.\u0004 ונמצא שניתן לפרש שהברייתא לענין מקדיש אילנות — לדעת ר' שמעון היא.","\u0003אמר רב הונא: חרוב המורכב וסדן השקמה\u0004 — \u0003תורת אילן עליו ותורת קרקע עליו;\u0004 כיצד? \u0003תורת אילן עליו, דהיכא דאקדיש\u0004 \u0005[שבמקום שהקדיש]\u0006 \u0003או זבין\u0004 \u0005[קנה]\u0006 \u0003שני אילנות והאי\u0004 \u0005[ו\u0006את \u0005זה]\u0006 החרוב או השקמה — \u0003יש לו קרקע,\u0004 שהוא מצטרף לשני האילנות האחרים, והריהם שלושה אילנות, שיש עמם קרקע. ומצד שני \u0003תורת קרקע עליו, דלא מזדבן\u0004 \u0005[שאינו נמכר]\u0006 \u0003אגב ארעא\u0004 \u0005[הקרקע]\u0006 כבמשנתנו, שהמוכר שדה לא מכר את החרוב המורכב וסדן השקמה שבו.","\u0003ואמר רב הונא\u0004 בסגנון דומה: \u0003עומר\u0004 גדול של תבואה \u0003שיש בו סאתים\u0004 (שתי סאים) — \u0003תורת עומר עליו ותורת גדיש עליו\u0004 לענין דיני שכחה; \u0003תורת עומר עליו,\u0004 שכלל הוא ש\u0003שני עומרים\u0004 ששכח אדם בשדה הריהם בדין \u0003שכחה\u0004 שאינו רשאי לחזור וללוקטם, ושלושה אינם שכחה. ולענין זה, אם שכח \u0003שנים\u0004 שני עומרים רגילים \u0003והוא\u0004 העומר בן הסאתים — \u0003אינן שכחה,\u0004 שהוא נחשב לעומר לענין זה שהוא מצטרף לעשות אותם כשלושה.","ומצד שני, \u0003תורת גדיש עליו, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003עומר שיש בו סאתים\u0004 ו\u0003שכחו\u0004 — \u0003אין שכחה\u0004 שמפני גודלו וחשיבותו אין בו דין שכחה, שהוא כגדיש.","ולעיקר ההלכה \u0003אמר רבה בר בר חנה אמר ריש לקיש:\u0004 בענין \u0003חרוב המורכב וסדן השקמה\u0004 האם מוקדשים הם בכלל שדה שהקדיש — \u0003באנו למחלוקת,\u0004 כלומר, נחלקו בדבר \u0003ר' מנחם בר' יוסי ורבנן\u0004 \u0005[וחכמים],\u0006 שר' מנחם סבור שאינם מוקדשים, וחכמים סבורים שכן\u0005.\u0006"],["ושואלים: \u0003ולימא\u0004 \u0005[ושיאמר]\u0006 שהיא \u0003מחלוקת ר' שמעון ורבנן\u0004 \u0005[וחכמים],\u0006 שהרי כך הגענו למסקנה לעיל, שלדעת ר' שמעון עצמו אף אלו אינם מוקדשים! ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו],\u0006 ש\u0003ר' מנחם בר' יוסי כר' שמעון סבירא ליה\u0004 \u0005[סבור הוא],\u0006 וזה היה החידוש שבדבריו, שיש חכם נוסף הסבור כר' שמעון.","","\u0003המוכר את הספינה\u0004 — \u0003מכר\u0004 יחד עמה \u0003את התורן ואת הנס ואת העוגין, ואת כל\u0004 כלי הספינה \u0003המנהיגין אותה. אבל לא מכר לא את העבדים\u0004 שמשיטים את הספינה, \u0003ולא את המרצופין\u0004 שהם עשויים להכניס בהם סחורה, \u0003ולא את האנתיקי\u0004 שהוא המקום שבו מכניסים אותם. \u0003ובזמן שאמר לו: \"היא וכל מה שבתוכה\u0004 מכורים לך \u0003\"\u0004— \u0003הרי כולן מכורין.\u0004","ותחילה מפרשים את האמור במשנה. \u0003\"תורן\"\u0004 פירושו בלשון ארמית \u0003איסקריא,\u0004 מוט הקבוע בספינה שעליו פרוש המפרש. \u0003וכן הוא אומר: \"ארז מלבנון לקחו לעשות תרן עליך\"\u0004 (יחזקאל כז, ה). \u0003\"נס\"\u0004 — \u0003אדרא,\u0004 כלומר, מפרש. \u0003וכן הוא אומר: \"שש ברקמה ממצרים היה מפרשך להיות לך לנס\"\u0004 (יחזקאל כז ז). \u0003\"עוגין\"\u0004 — \u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא: אלו עוגינין שלה,\u0004 העוגן שמחזיק אותה במקום אחד. \u0003וכן הוא אומר: \"הלהן תשברנה עד אשר יגדלו הלהן תעגנה לבלתי היות לאיש\"\u0004 (רות א, יג), ומכאן שלשון \"עיגון\" משמעה — קביעה ועיכוב במקום אחד.","\u0003\"מנהיגין\"\u0004 — \u0003אמר ר' אבא: אלו המשוטין שלה. וכן הוא אומר: \"אלונים מבשן עשו משוטיך\"\u0004 (יחזקאל כז, ו). \u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 ראיה \u0003מהכא\u0004 \u0005[מכאן],\u0006 שנאמר: \u0003\"וירדו מאניותיהם כל תפשי משוט\"\u0004 (יחזקאל כז, כט).","ועוד בענין מכירת ספינה והכלול בה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003המוכר את הספינה\u0004 — \u0003מכר את האיסכלה\u0004 (סולם), הכבש שעולים בו לספינה, \u0003ואת בור המים שבתוכה. ר' נתן אומר: המוכר את הספינה\u0004 — \u0003מכר את הביצית,\u0004 סירה קטנה שיש באוניה לצורך הצלה, או על מנת לדוג במקומות רדודים. \u0003סומכוס אומר: המוכר את הספינה\u0004 — \u0003מכר את הדוגית.\u0004","\u0003אמר רבא: ביצית היינו דוגית,\u0004 שבעצם לא נחלקו ואמרו שניהם דבר אחד, אלא \u0003ר' נתן בבלאה הוה\u0004 \u0005[בבלי היה],\u0006 ולכן \u0003קארי\u0004 \u0005[קורא\u0006 היה\u0005]\u0006 \u0003לה\u0004 \u0003\"בוצית\", כדאמרי אינשי\u0004 \u0005[כמו שאומרים אנשים\u0006 בבבל\u0005]:\u0006 \u0003בוציאתא דמיאשן\u0004 \u0005[הבוציות,\u0006 הסירות הקטנות \u0005של מישן];\u0006 ואילו \u0003סומכוס, דבר\u0004 \u0005[שבן]\u0006 \u0003ארץ ישראל\u0004 הוא, \u0003קארי\u0004 \u0005[קורא\u0006 היה\u0005]\u0006 \u0003לה \"דוגית\", כדכתיב\u0004 \u0005[כפי שנאמר]:\u0006 \u0003\"ואחריתכן בסירות דוגה\"\u0004 (עמוס ד, ב).","כיון שהוזכרו הלכות הנוגעות לספינה, מביאים כאן כמה סיפורים הנוגעים בספינות ובשיחות יורדי הים. \u0003אמר רבה, אשתעו\u0004 \u0005[סיפרו]\u0006 \u0003לי נחותי ימא\u0004 \u0005[יורדי הים]:\u0006 \u0003האי גלא\u0004 \u0005[הגל הזה]\u0006 ש\u0003מטבע לספינה,\u0004 \u0003מיתחזי כי צוציתא דנורא חיוורתא ברישא\u0004 \u0005[נראה כמו זוהר של אש לבנה בראשו],\u0006 \u0003ו\u0004כדי להינצל ממנו \u0003מחינן ליה באלוותא דחקיק עליה\u0004 \u0005[מכים אנו אותו באלות שחקוק עליהן]\u0006 שמות קדושים: \u0003\"אהיה אשר אהיה יה ה' צבאות אמן אמן סלה\", ונייח\u0004 \u0005[ו\u0006אז \u0005נח\u0006 הגל\u0005].\u0006 ועוד \u0003אמר רבה, אשתעו\u0004 \u0005[סיפרו]\u0006 \u0003לי נחותי ימא\u0004 \u0005[יורדי הים]:\u0006 \u0003בין גלא לגלא תלת מאה פרסי\u0004 \u0005[בין גל לגל שלוש מאות פרסות],\u0006 \u0003ורומא דגלא תלת מאה פרסי\u0004 \u0005[וגובה הגל שלוש מאות פרסות].\u0006 \u0003זימנא חדא הוה אזלינן באורחא\u0004 \u0005[פעם אחת היינו הולכים בדרך],\u0006 \u0003ודלינן גלא\u0004 \u0005[והגביה אותנו הגל]\u0006 \u0003עד דחזינן בי מרבעתיה דכוכבא זוטא\u0004 \u0005[שראינו\u0006 את \u0005בית מרבצו,\u0006 מושבו \u0005של כוכב קטן],\u0006 \u0003והויא לי כמבזר ארבעין גריוי בזרא דחרדלא\u0004 \u0005[והיה\u0006 גודלו \u0005כמו\u0006 מקום \u0005שזורעים בו ארבעים סאים של זרע חרדל],\u0006 \u0003ואי דלינן טפי\u0004 \u0005[ואם היה מגביה אותנו יותר]\u0006 — \u0003הוה מקלינן מהבליה\u0004 \u0005[היינו נשרפים מחומו\u0006 של הכוכב\u0005].\u0006","","\u0003ורמי לה גלא קלא לחברתה\u0004 \u0005[וזרק לו הגל קול,\u0006 צעק \u0005לחבירו]:\u0006 \u0003\"חבירתי,\u0004 האם \u0003שבקת מידי בעלמא\u0004 \u0005[הנחת דבר בעולם]\u0006 ש\u0003לא שטפתיה\u0004 \u0005[שטפת אותו],\u0006 \u0003דניתי אנא ונאבדיה\u0004 \u0005[שאבוא אני ואאבד אותו]\u0006 \u0003\"?\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 הגל האחר: \u0003\"פוק חזי גבורתא דמריך\u0004 \u0005[צא וראה גבורת אדוניך,\u0006 הקדוש ברוך הוא\u0005],\u0006 \u0003מלא חוטא חלא ולא עברי\u0004 \u0005[מלוא חוט חול\u0006 ביבשה \u0005ואיני עובר],\u0006 \u0003שנאמר: \"האותי לא תיראו נאם ה' אם מפני לא תחילו אשר שמתי חול גבול לים חק עולם ולא יעברנהו\"\u0004 (ירמיה ה, כב).","ועוד \u0003אמר רבה: לדידי חזי לי\u0004 \u0005[אני עצמי ראיתי]\u0006 אותו שקוראים לו \u0003\"הורמין בר לילית\", כי קא רהיט אקופיא דשורא\u0004 \u0005[כאשר היה רץ על שיני חומת]\u0006 העיר \u0003מחוזא,\u0004 \u0003ורהיט פרשא כי רכיב חיותא מתתאיה\u0004 \u0005[והיה רץ פרש כאשר\u0006 הוא \u0005רוכב\u0006 על \u0005בהמות מתחתיו]\u0006 \u0003ולא יכיל ליה\u0004 \u0005[היה יכול לו\u0006 להשיגו\u0005].\u0006 \u0003זמנא חדא הוה מסרגאן ליה תרתי כודנייתי\u0004 \u0005[פעם אחת היו חבושות לו שתי פרדות]\u0006 \u0003וקיימן\u0004"],["\u0003אתרי גישרי\u0004 \u0005[על שני הגשרים]\u0006 של הנהר \u0003רוגנג,\u0004 \u0003ושואר מהאי להאי ומהאי להאי\u0004 \u0005[וקפץ מזה לזה ומזה לזה],\u0006 \u0003ונקיט תרי מזגי דחמרא בידיה\u0004 \u0005[והיה מחזיק שתי כוסות יין בידו],\u0006 \u0003ומוריק מהאי להאי ומהאי להאי\u0004 \u0005[ושופך מזו לזו ומזו לזו]\u0006 \u0003ולא נטפא ניטופתא לארעא\u0004 \u0005[נטפו נטפים לארץ],\u0006 \u0003ואותו היום\u0004 שאירע בו הדבר, יום סערה, כגון שנאמר ביורדי הים ביום שכזה: \u0003\"יעלו שמים ירדו תהומות\"\u0004 (תהלים קז, כו) \u0003הוה\u0004 \u0005[היה],\u0006 \u0003עד\u0004 ש\u0003שמעו בי מלכותא וקטלוהו\u0004 \u0005[\u0006ב\u0005בית המלוכה והרגו אותו].\u0006","\u0003אמר רבה: לדידי חזי לי אורזילא בר יומיה\u0004 \u0005[אני ראיתי ראם בן יומו]\u0006 \u0003דהוה\u0004 \u0005[שהיה]\u0006 גדול \u0003כהר תבור, והר תבור כמה הוי\u0004 \u0005[הוא]?\u0006 \u0003ארבע פרסי\u0004 \u0005[פרסות].\u0006 \u0003ומשאכא דצואריה תלתא פרסי\u0004 \u0005[ואורך צווארו שלוש פרסות],\u0006 \u0003ובי מרבעתא דרישיה פרסא ופלגא\u0004 \u0005[ומקום הנחת ראשו פרסה ומחצה].\u0006 \u0003רמא כופתא וסכר ליה לירדנא\u0004 \u0005[הטיל גלל וסכר על ידו את הירדן].\u0006","\u0003ואמר רבה בר בר חנה: לדידי חזיא לי ההיא אקרוקתא דהויא כי אקרא\u0004 \u0005[אני ראיתי צפרדע אחת שהיתה\u0006 גדולה \u0005כמו מבצר]\u0006 \u0003הגרוניא,\u0004 \u0003ואקרא\u0004 \u0005[המבצר]\u0006 של \u0003הגרוניא כמה הויא\u0004 \u0005[הוא]?\u0006 \u0003שתין בתי\u0004 \u0005[\u0006כ\u0005שישים בתים].\u0006 \u0003אתא תנינא\u0004 \u0005[בא תנין]\u0006 \u0003בלעה\u0004 את הצפרדע, \u0003אתא פושקנצא ובלעה לתנינא\u0004 \u0005[בא עורב ובלע את התנין]\u0006 \u0003וסליק יתיב באילנא\u0004 \u0005[ועלה וישב באילן].\u0006 \u0003תא חזי\u0004 \u0005[בוא וראה]\u0006 \u0003כמה נפיש חיליה דאילנא\u0004 \u0005[גדול כוחו של האילן]\u0006 שיכול לשאת אותו. \u0003אמר רב פפא בר שמואל: אי\u0004 \u0005[אם]\u0006 \u0003לא הואי התם\u0004 \u0005[הייתי שם]\u0006 ורואה זאת, \u0003לא הימני\u0004 \u0005[\u0006\u0005הייתי מאמין].\u0006","\u0003ואמר רבה בר בר חנה: זימנא חדא הוה קא אזלינן בספינתא\u0004 \u0005[פעם אחת היינו הולכים בספינה],\u0006 \u0003וחזינן ההוא כוורא דיתבא ליה אכלה טינא באוסייה\u0004 \u0005[וראינו דג אחד שישבה לו אוכלת טיט,\u0006 מין שרץ \u0005בנחיריו\u0006 והרגתו\u0005],\u0006 \u0003ואדחוהו מיא ושדיוהו לגודא\u0004 \u0005[ודחו אותו המים\u0006 את הדג, \u0005וזרקוהו לחוף].\u0006 \u0003וחרוב מיניה שתין מחוזי\u0004 \u0005[ונחרבו ממנו,\u0006 מאותו דג שהושלך, \u0005ששים מחוזות],\u0006 \u0003ואכול מיניה שתין מחוזי\u0004 \u0005[ואכלו ממנו,\u0006 מבשרו, \u0005ששים מחוזות],\u0006 \u0003ומלחו מיניה\u0004 \u0005[ממנו]\u0006 כדי לשמר את בשרו עוד \u0003שתין מחוזי\u0004 \u0005[ששים מחוזות],\u0006 \u0003ומלאו מחד גלגלא דעיניה תלת מאה גרבי משחא\u0004 \u0005[ומילאו מגלגל אחד של עינו שלוש מאות נאדות שמן].\u0006 \u0003וכי הדרן לבתר תריסר ירחי שתא\u0004 \u0005[וכאשר חזרנו\u0006 לשם \u0005לאחר שנים עשר חודשי שנה],\u0006 \u0003חזינן דהוה קא מנסרי מגרמי מטללתא\u0004 \u0005[ראינו שהיו מנסרים מעצמותיו קורות],\u0006 \u0003ויתבי למבנינהו הנך מחוזי\u0004 \u0005[ויושבים לבנות אותם המחוזות\u0006 שנחרבו\u0005].\u0006","\u0003ואמר רבה בר בר חנה: זימנא חדא הוה קא אזלינן בספינתא\u0004 \u0005[פעם אחת היינו הולכים בספינה],\u0006 \u0003וחזינן ההוא כוורא דיתבא ליה חלתא אגביה וקדח אגמא עילויה\u0004 \u0005[וראינו דג אחד שישב לו חול על גבו וצמח עשב עליו],\u0006 \u0003סברינן יבשתא\u0004 \u0005[חשבנו\u0006 ש\u0005יבשה]\u0006 \u0003היא, וסלקינן ואפינן ובשלינן אגביה\u0004 \u0005[ועלינו ואפינו ובישלנו על גבו],\u0006 \u0003וכד חם גביה אתהפיך\u0004 \u0005[וכאשר התחמם גבו התהפך],\u0006 \u0003ואי לאו דהוה מקרבא ספינתא, הוה טבעינן\u0004 \u0005[ואם לא שהיתה קרובה הספינה\u0006 אלינו, \u0005היינו טובעים].\u0006","\u0003ואמר רבה בר בר חנה: זימנא חדא הוה אזלינן בספינתא\u0004 \u0005[פעם אחת היינו הולכים בספינה],\u0006 \u0003וסגאי ספינתא בין שיצא לשיצא דכוארא תלתא יומי ותלתא לילוותא\u0004 \u0005[והלכה הספינה בין סנפיר לסנפיר,\u0006 כלומר, לאורכו \u0005של דג\u0006 אחד בין ראשו לזנבו \u0005שלושה ימים ושלושה לילות],\u0006 והוא היה שט בכיוון הנגדי לספינה, כאשר \u0003איהו בזקיפא ואנן בשיפולא\u0004 \u0005[הוא במעלה\u0006 הים, כלומר, כנגד כיוון הרוח והגלים \u0005ואנו בירידה].\u0006 \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003לא מסגיא ספינתא טובא\u0004 \u0005[הלכה הספינה הרבה,\u0006 מהר\u0005],\u0006 ולכן הלכה הספינה שלושה ימים עד שחלפה על פני הדג, הרי \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי אמר:\u0004 ספינה זו, \u0003כמיחם קומקומא דמיא מסגיא שתין פרסי\u0004 \u0005[כ\u0006זמן הנדרש ל\u0005חימום קומקום של מים,\u0006 שהוא זמן קצר ביותר, \u0005הולכת\u0006 הספינה \u0005ששים פרסות],\u0006 \u0003ושאדי פרשא גירא וקדמה ליה\u0004 \u0005[ויורה פרש חץ ו\u0006היא \u0005קודמת לו\u0006 לחץ\u0005]\u0006 מרוב מהירותה. \u0003ואמר רב אשי: ההוא גילדנא דימא הואי, דאית ליה תרי שייצי\u0004 \u0005[אותו\u0006 דג \u0005גילדן הים היה, שיש לו שני סנפירים].\u0006","\u0003ואמר רבה בר בר חנה: זימנא חדא הוה אזלינן בספינתא\u0004 \u0005[פעם אחת היינו הולכים בספינה],\u0006 \u0003וחזינן ההוא ציפרא דקאים\u0004 \u0005[וראינו ציפור אחת שעומדת]\u0006 \u0003עד קרצוליה במיא\u0004 \u0005[קרסוליה במים]\u0006 \u0003ורישיה\u0004 \u0005[וראשה]\u0006 \u0003ברקיע,\u0004 \u0003ואמרינן ליכא מיא, ובעינן לחות לאקורי נפשין\u0004 \u0005[ואמרנו\u0006 לעצמנו \u0005אין כאן מים\u0006 עמוקים, \u0005ורצינו לרדת לקרר עצמנו],\u0006 \u0003ונפק בת קלא ואמר לן\u0004 \u0005[ויצאה בת קול ואמרה לנו]:\u0006 \u0003לא תיחותו הכא\u0004 \u0005[אל תרדו כאן],\u0006 \u0003דנפלת ליה חציצא לבר נגרא הא שב שני\u0004 \u0005[שנפל לו\u0006 כאן \u0005גרזן לנגר זה שבע שנים]\u0006 \u0003ו\u0004עדיין \u0003לא קא מטיא אארעא\u0004 \u0005[הגיע לקרקעית],\u0006 \u0003ולאו\u0004 \u0005[ולא]\u0006 \u0003משום דנפישי מיא\u0004 \u0005[שמרובים,\u0006 עמוקים\u0005, המים]\u0006 \u0003אלא משום דרדפי מיא\u0004 \u0005[שסוערים המים].\u0006 \u0003אמר רב אשי: וההוא\u0004 \u0005[אותו]\u0006 עוף \u0003זיז שדי הוא, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004ידעתי כל עוף הרים \u0003וזיז שדי עמדי\"\u0004 (תהלים נ, יא).","\u0003ואמר רבה בר בר חנה: זימנא חדא הוה קא אזלינן במדברא\u0004 \u0005[פעם אחת היינו הולכים במדבר],\u0006 \u0003וחזינן הנהו אווזי דשמטי גדפייהו משמנייהו\u0004 \u0005[וראינו אווזים ששמוטות כנפיהם מ\u0006רוב \u0005שומנם]\u0006 \u0003וקא נגדי נחלי דמשחא מתותייהו\u0004 \u0005[ויורדים נחלי שמן מתחתם].\u0006 \u0003אמינא להו\u0004 \u0005[אמרתי להם]:\u0006 \u0003אית לן בגוייכו חלקא לעלמא דאתי\u0004 \u0005[יש לנו בכם חלק לעולם הבא]?\u0006 \u0003חדא דלי גדפא, וחדא דלי אטמא\u0004 \u0005[אחד הרים\u0006 לי \u0005כנף, ואחד הרים\u0006 לי \u0005רגל]\u0006 כאומרים \"כן\". \u0003כי אתאי לקמיה\u0004 \u0005[כאשר באתי לפני]\u0006 \u0003ר' אלעזר, אמר לי: עתידין ישראל ליתן עליהן את הדין\u0004 שאינם עושים תשובה, ואווזים אלה, העומדים וממתינים לינתן להם בשכרם, סובלים, משום שהם משמינים והולכים.","\u0003(סימן\u0004 לדברים שהראה ערבי אחד לרבה בר בר חנה: \u0003כעפרא דתכילתא טרקתיה עקרבא לסלתיה\u0004 \u0005[כעפר של תכלת עקצו עקרב לסלו]\u0006","\u0003). ואמר רבה בר בר חנה: זימנא חדא הוה קא אזלינן במדברא\u0004 \u0005[פעם אחת היינו הולכים במדבר],\u0006 \u0003ואיתלוי בהדן ההוא טייעא\u0004 \u0005[ונתלווה עמנו ערבי אחד]\u0006 \u0003דהוה שקיל עפרא ומורח ליה ואמר\u0004 \u0005[ושהיה לוקח עפר ומריח אותו ואומר]:\u0006 \u0003הא אורחא לדוכתא פלן, והא אורחא לדוכתא פלן\u0004 \u0005[זו הדרך למקום פלוני, וזו הדרך למקום פלוני]\u0006 לפי ריח העפר, \u0003אמרינן ליה\u0004 \u0005[אמרנו לו]:\u0006 \u0003כמה מרחקינן ממיא\u0004 \u0005[רחוקים אנו ממים]?\u0006 \u0003ואמר לן\u0004 \u0005[לנו]:\u0006 \u0003הבו\u0004 \u0005[תנו]\u0006 \u0003לי עפרא\u0004 \u0005[עפר]\u0006 להריח, \u0003יהבינן ליה\u0004 \u0005[נתנו לו],\u0006 \u0003ואמר לן\u0004 \u0005[לנו]:\u0006 \u0003תמני פרסי\u0004 \u0005[שמונה פרסות].\u0006 \u0003תנינן ויהבינן ליה\u0004 \u0005[שנינו\u0006 פעם שניה \u0005ונתנו לו\u0006 שוב\u0005],\u0006 ו\u0003אמר לן\u0004 \u0005[לנו]\u0006 \u0003דמרחקינן תלתא פרסי\u0004 \u0005[שאנו רחוקים שלוש פרסות].\u0006 \u0003אפכית ליה\u0004 \u0005[הפכתי לו]\u0006 את מיני העפר לנסותו, \u0003ולא יכילית ליה\u0004 \u0005[יכולתי לו]\u0006 שבאמת היה בקיא.","\u0003אמר לי\u0004 אותו ערבי: \u0003תא אחוי\u0004 \u0005[בוא\u0006 ו\u0005אראה]\u0006 \u0003לך\u0004 את \u0003מתי מדבר,\u0004 בני ישראל יוצאי מצרים, שמתו בשעתם במדבר. \u0003אזלי, חזיתינהו\u0004 \u0005[הלכתי, ראיתי אותם]\u0006 \u0003ודמו כמאן דמיבסמי\u0004 \u0005[ונראים\u0006 היו \u0005כמו שמשתכרים]\u0006"]]};
